-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 3: a prova nova Revalida 2026/2 com o GABARITO PRELIMINAR do Inep.
-- Gerado por scripts/carga-provas/gerar-pacote.mjs (ramo carga-provas). Não edite à mão.
-- O que faz:
--   * cria a prova "Revalida INEP 2026/2 — 2ª Edição Semestral" (revalida-2026-2) e 100 questões (texto do caderno 1, conferido com o PDF);
--   * registra para cada uma o gabarito oficial PRELIMINAR (fonte: gabarito preliminar do Inep), com a observação
--     "Gabarito preliminar: questão do Revalida 2026/2, ainda sem gabarito definitivo do Inep" no histórico da questão;
--   * o aluno vê em TODAS elas (treino, correção, resultado da sessão, caderno de erros) o selo "GABARITO PRELIMINAR" e a frase
--     "O gabarito definitivo só será divulgado pelo Inep em 04/12/2026." (precisa da parte 1). A data fica gravada na prova
--     (exams.final_answer_expected_on), é DADO: para trocar, um update nessa coluna, sem publicar o site. Data informada pelo dono;
--     confirmar no cronograma do Inep. O definitivo entra depois pela função oficial de registro de gabarito (situação FINAL) e o selo some.
--   * as 16 questões com figura ou tabela entram com a marca "cita figura": ficam FORA dos treinos até a parte 4 ligar as imagens.
--   * tema provisório "Revalida 2026/2 · Qnn · tema a classificar" (o tema de verdade vem na carga das explicações).
-- Pode colar de novo: questão que já existe não é mexida; gabarito já registrado não é trocado (nunca rebaixa um definitivo).
-- Como colar: editor SQL do Supabase, arquivo INTEIRO, Run. Primeira linha: "OK: ...".
-- =============================================================================
create temp table if not exists _carga_2026_2_resultado (questao text, situacao text);
delete from _carga_2026_2_resultado;

do $carga_2026_2$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2026_2_q001","code":"REV-2026.2-Q001","number":1,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q01 · tema a classificar","statement":"Homem de 75 anos, residente em instituição de longa permanência, com histórico de declínio cognitivo leve, é levado a uma Unidade Básica de Saúde devido a quadro de confusão mental progressiva iniciado há 7 dias, associado a astenia, tosse e agitação psicomotora. No segundo dia de sintomas, foi iniciada ciprofloxacina empiricamente, sem melhora. O paciente apresenta hipertensão arterial e dislipidemia bem controladas. O exame físico revela: paciente confuso no tempo e no espaço; temperatura axilar 36,1 °C; PA 110 x 60 mmHg; FC 98 bpm; FR 21 irpm; SatO₂ 94% em ar ambiente. Ausculta respiratória com estertores finos em bases bilateralmente. Qual é a conduta inicial para esse paciente?","options":[{"id":"A","text":"Associar claritromicina.","explanation":""},{"id":"B","text":"Encaminhar para Unidade de Pronto Atendimento.","explanation":""},{"id":"C","text":"Solicitar tomografia de tórax.","explanation":""},{"id":"D","text":"Administrar furosemida.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q002","code":"REV-2026.2-Q002","number":2,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q02 · tema a classificar","statement":"Criança de 4 anos, previamente saudável, é levada a uma Unidade de Pronto Atendimento após início súbito de dificuldade respiratória, estridor inspiratório intenso, sialorreia, postura sentada em tripé, aspecto tóxico e rebaixamento de nível de consciência. A mãe relata que a criança estava bem até poucas horas antes do episódio. Ao exame: FC 160 bpm; FR 50 irpm; SatO₂ 86% em ar ambiente; temperatura axilar 40 °C. A criança apresenta piora da dispneia à manipulação. Qual é a principal hipótese diagnóstica nesse caso?","options":[{"id":"A","text":"Laringite aguda.","explanation":""},{"id":"B","text":"Obstrução por corpo estranho.","explanation":""},{"id":"C","text":"Epiglotite aguda.","explanation":""},{"id":"D","text":"Pneumonia bacteriana.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q003","code":"REV-2026.2-Q003","number":3,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q03 · tema a classificar","statement":"Gestante de 32 semanas é socorrida por equipe de atendimento pré-hospitalar após sofrer acidente automobilístico. A paciente está conversando. Apresenta: escala de Glasgow 12; FC 108 bpm; PA 90 x 60 mmHg. É imobilizada em prancha rígida com colar cervical. Qual é a conduta indicada para otimizar o retorno venoso materno, durante o transporte, sem risco de comprometer a estabilização da coluna vertebral da paciente?","options":[{"id":"A","text":"Colocá-la em posição de Trendelemburg.","explanation":""},{"id":"B","text":"Imobilizá-la na prancha em decúbito lateral esquerdo.","explanation":""},{"id":"C","text":"Realizar o deslocamento manual do útero para a esquerda.","explanation":""},{"id":"D","text":"Elevar os membros inferiores.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q004","code":"REV-2026.2-Q004","number":4,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q04 · tema a classificar","statement":"Mulher de 35 anos, nuligesta, comparece à consulta em Unidade Básica de Saúde com queixa de dismenorreia progressiva e de hematoquezia quando está menstruada. Relata que as cólicas menstruais pioraram há 5 anos e que precisou procurar o pronto-socorro em duas ocasiões por dor pélvica forte e necessidade de medicação intravenosa. Afirma não fazer uso de contracepção hormonal por não ter atividade sexual há 10 anos. Nega doenças crônicas ou uso de medicações. Refere constipação, com piora nos últimos 6 meses, e distensão abdominal. Ao exame físico, observa-se abdome indolor à palpação; exame especular sem lesões visíveis; toque vaginal com dor à mobilização do colo uterino; útero pouco móvel; palpação de nódulos endurecidos e doloridos em fórnice vaginal posterior. Considerando-se a provável hipótese diagnóstica, qual é o exame de referência para investigação inicial nesse caso?","options":[{"id":"A","text":"Tomografia computadorizada do abdome.","explanation":""},{"id":"B","text":"Laparoscopia diagnóstica.","explanation":""},{"id":"C","text":"Histerossonossalpingografia.","explanation":""},{"id":"D","text":"Ultrassonografia endovaginal.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q005","code":"REV-2026.2-Q005","number":5,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q05 · tema a classificar","statement":"Homem de 27 anos procura Unidade Básica de Saúde referindo febre, mialgia, artralgia, cefaleia e dor retro-orbitária, iniciadas há 7 dias. Relatou vômitos frequentes há 2 dias. Nega ter viajado nas últimas 2 semanas. O exame físico mostra: temperatura axilar 39 °C; desidratado (2+/4+); PA 80 x 50 mmHg; FC 120 bpm; FR 22 irpm; abdome com dor difusa à palpação profunda; exantema maculopapular em tronco e membros superiores. A confirmação do diagnóstico provável nesse caso será determinada por","options":[{"id":"A","text":"pesquisa de proteína NS1.","explanation":""},{"id":"B","text":"avaliação da contagem de plaquetas.","explanation":""},{"id":"C","text":"realização de isolamento viral.","explanation":""},{"id":"D","text":"detecção de Anticorpos IgM por ELISA.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q006","code":"REV-2026.2-Q006","number":6,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q06 · tema a classificar","statement":"Em uma reunião de equipe, a enfermeira da Unidade Básica de Saúde (UBS) informa que, apesar de estar conseguindo manter os atendimentos de rotina, no último mês percebeu aumento de atendimentos por desidratação leve, exaustão pelo calor e descompensação de doenças crônicas, e que suspeita estarem relacionadas à onda de calor que está ocorrendo no município. O plano de intervenção para a população do território adstrito dessa UBS consiste em","options":[{"id":"A","text":"separar o fluxo de atendimento da UBS para agilizar o atendimento da população atingida.","explanation":""},{"id":"B","text":"implementar hospital de campanha para atender a população por demanda espontânea.","explanation":""},{"id":"C","text":"encaminhar as pessoas afetadas para hidratação parenteral a fim de evitar descompensação clínica.","explanation":""},{"id":"D","text":"orientar hidratação, adaptação do domicílio, sinais de alerta, e monitoramento ativo dos susceptíveis.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q007","code":"REV-2026.2-Q007","number":7,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q07 · tema a classificar","statement":"Estudante de 17 anos comparece espontaneamente a uma Unidade Básica de Saúde com relato de tristeza e dificuldade de relacionamento com os pais. Refere que já pensou em “sumir” depois da última briga em casa, mas nega intenção ou planejamento suicida, afirmando que não quer morrer, “só queria que esse sentimento ruim passasse”. Segundo seu relato, perdeu interesse nas atividades do dia a dia e, nos últimos meses, passou a maior parte do tempo em seu quarto, mas tem mantido sono regular, apetite inalterado, bom desempenho escolar, além de funcionalidade preservada. Afirma não usar substâncias psicoativas e nega comportamentos autolesivos ou tentativas de suicídio anteriores. Considerando o quadro apresentado e o manejo na atenção primária, a conduta inicial para esse paciente é","options":[{"id":"A","text":"convocar seus responsáveis e encaminhá-lo ao Centro de Atenção Psicossocial infantojuvenil do território de referência.","explanation":""},{"id":"B","text":"prescrever inibidor de recaptação de serotonina e encaminhá-lo para acompanhamento em ambulatório de saúde mental.","explanation":""},{"id":"C","text":"propor o envolvimento da família no cuidado e iniciar acompanhamento multidisciplinar na Unidade Básica de Saúde.","explanation":""},{"id":"D","text":"explicar-lhe que a distimia faz parte da adolescência, orientá-lo a aguardar e sugerir que busque o serviço de emergência em caso de piora.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q008","code":"REV-2026.2-Q008","number":8,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q08 · tema a classificar","statement":"Mulher de 56 anos, hipertensa mal controlada, com obesidade grau 3, tabagista ativa de 60 maços/ano, procura uma Unidade de Pronto Atendimento por dor torácica, iniciada há 2 horas e 30 minutos. A dor é do tipo queimação, retroesternal, que piora com esforço e melhora com repouso. O eletrocardiograma demonstrou infradesnivelamento do segmento ST > 0,5 mm em V1, V2, V3 e V4. Foi realizada dosagem de troponina de alta sensibilidade à admissão, com resultado de 6 ng/L (VR: até 9 ng/L). Após administração de nitrato e morfina, a paciente está hemodinamicamente estável e sem dor. Qual é a próxima conduta no manejo dessa paciente?","options":[{"id":"A","text":"Iniciar terapia trombolítica em até 30 minutos.","explanation":""},{"id":"B","text":"Encaminhar para cateterismo coronariano de urgência.","explanation":""},{"id":"C","text":"Realizar nova dosagem de troponina em 1 hora.","explanation":""},{"id":"D","text":"Repetir eletrocardiograma em 2 horas.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q009","code":"REV-2026.2-Q009","number":9,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q09 · tema a classificar","statement":"Escolar de 8 anos, asmático prévio sem tratamento intercrises e com uso frequente de salbutamol de resgate (4 vezes nos últimos 6 meses), deu entrada em uma Unidade de Pronto Atendimento em crise aguda de asma. Na admissão, apresentava fala entrecortada, FR 40 irpm, SatO₂ 90% em ar ambiente, FC 112 bpm, murmúrio vesicular abafado e retração de fúrcula. Foi monitorizado, prescrito corticoide via oral e 3 ciclos de salbutamol e ipratrópio por via inalatória. Após o tratamento inicial, o paciente mantém fala entrecortada, FR 42 irpm, SatO₂ 92% em ar ambiente, FC 128 bpm, sibilos difusos, retração de fúrcula, uso de musculatura abdominal e tempo expiratório prolongado. A conduta medicamentosa após o tratamento inicial é administrar","options":[{"id":"A","text":"sulfato de magnésio.","explanation":""},{"id":"B","text":"corticoide.","explanation":""},{"id":"C","text":"anti-histamínico.","explanation":""},{"id":"D","text":"terbutalina.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q010","code":"REV-2026.2-Q010","number":10,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q10 · tema a classificar","statement":"Homem de 45 anos, sem comorbidades, realizou hernioplastia inguinal aberta com tela há 7 dias, e retorna ao ambulatório com dor no local da cirurgia. Nega febre ou calafrios. Ao exame físico, apresenta, no terço médio da ferida operatória: área de tumefação; rubor e calor. Não há evidências de acometimento de fáscia ou plano muscular. Diante do quadro apresentado, qual é a conduta nesse momento?","options":[{"id":"A","text":"Prescrever antibioticoterapia oral.","explanation":""},{"id":"B","text":"Remover a tela.","explanation":""},{"id":"C","text":"Explorar localmente a ferida.","explanation":""},{"id":"D","text":"Solicitar ultrassonografia de partes moles.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q011","code":"REV-2026.2-Q011","number":11,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q11 · tema a classificar","statement":"Gestante de 38 anos, G3PC1A1, com 38 semanas de gestação, comparece a um pronto atendimento referindo sangramento vaginal, iniciado há 1 hora. Ela descreve o sangramento como moderado, de cor vermelho vivo, e afirma que iniciou após um episódio de forte dor abdominal. Relata que, desde então, o útero permanece “muito duro” e que percebeu redução dos movimentos fetais. Nega perda de líquido. A paciente possui histórico de hipertensão gestacional na gravidez atual. Ao exame físico, mostra-se pálida, com PA 150 x 95 mmHg e FC 105 bpm. O abdome está doloroso à palpação, com hipertonia uterina. Identifica-se batimento cardíaco fetal variando de 100 a 110 bpm de forma sustentada. A inspeção especular revela moderada quantidade de sangue vermelho vivo no fundo vaginal. Qual é a conduta imediata nessa situação?","options":[{"id":"A","text":"Interromper a gestação pela via de parto mais rápida.","explanation":""},{"id":"B","text":"Confirmar a localização placentária por ultrassonografia obstétrica.","explanation":""},{"id":"C","text":"Realizar perfil biofísico fetal com monitorização dos sinais vitais maternos.","explanation":""},{"id":"D","text":"Iniciar a indução do trabalho de parto.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q012","code":"REV-2026.2-Q012","number":12,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q12 · tema a classificar","statement":"Homem de 42 anos, em situação de rua, comparece a uma Unidade Básica de Saúde (UBS) em atendimento de demanda espontânea, apresentando adinamia, tosse persistente, febre vespertina e perda de peso. Relata diagnóstico de tuberculose pulmonar há 6 meses e início de tratamento em outra UBS, interrompido após cerca de 3 semanas por dificuldades relacionadas à instabilidade de moradia e ao acesso a serviços. No momento do atendimento, não apresenta documentação pessoal e refere receio em retomar o tratamento, relatando experiências anteriores de discriminação nos serviços de saúde. Como parte do plano terapêutico singular, onde deve ser reiniciado o tratamento para esse paciente?","options":[{"id":"A","text":"Na UBS atual, na qual compareceu para atendimento.","explanation":""},{"id":"B","text":"Na UBS de origem, na qual o tratamento foi iniciado.","explanation":""},{"id":"C","text":"No Consultório na Rua responsável pela região.","explanation":""},{"id":"D","text":"Em unidade hospitalar, com médico pneumologista.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q013","code":"REV-2026.2-Q013","number":13,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q13 · tema a classificar","statement":"Uma equipe de saúde da família observa um aumento de crises hipertensivas entre pacientes diagnosticados com hipertensão arterial sistêmica acompanhados pela equipe nos últimos 3 meses. A revisão dos dados revela redução da adesão aos grupos educativos sobre hipertensão, diminuição nos registros de pressão arterial e menor comparecimento às consultas programadas. As visitas domiciliares estão aquém do necessário, devido à redução do número de agentes comunitários no território. Qual é a medida prioritária a ser adotada pela equipe de saúde para solucionar essa situação na atenção primária?","options":[{"id":"A","text":"Desenvolver ações educativas para o controle de condições de risco.","explanation":""},{"id":"B","text":"Identificar as falhas no cuidado e no fluxo de informação.","explanation":""},{"id":"C","text":"Analisar o número de visitas domiciliares como indicador.","explanation":""},{"id":"D","text":"Encaminhar para acompanhamento ambulatorial especializado.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q014","code":"REV-2026.2-Q014","number":14,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q14 · tema a classificar","statement":"Adolescente de 14 anos foi levada a uma Unidade Básica de Saúde pelos pais por apresentar “medo intenso de engordar”. Refere preocupação excessiva com ganho de peso há 1 ano, razão pela qual tem feito restrição alimentar progressiva durante o dia. Relata, porém, episódios de compulsão alimentar quase todas as noites da semana, nos últimos 4 meses, quando não consegue controlar a quantidade e a qualidade do que come. Menciona compensar os episódios de compulsão alimentar com jejuns prolongados e exercícios físicos excessivos. Nega histórico de vômitos autoinduzidos ou uso de laxantes. Não há comorbidades clínicas prévias. O exame físico revela: paciente consciente e orientada; sinais vitais estáveis; IMC 23 kg/m²; pele levemente ressecada e ausência de sinais de desnutrição ou outras alterações. Qual é a principal hipótese diagnóstica nesse caso?","options":[{"id":"A","text":"Anorexia nervosa.","explanation":""},{"id":"B","text":"Transtorno alimentar não especificado.","explanation":""},{"id":"C","text":"Bulimia nervosa.","explanation":""},{"id":"D","text":"Transtorno de compulsão alimentar.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q015","code":"REV-2026.2-Q015","number":15,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q15 · tema a classificar","statement":"Homem de 64 anos, agricultor, residente em zona rural, está em investigação em uma Unidade Básica de Saúde por insuficiência cardíaca com fração de ejeção reduzida. De antecedentes relevantes, informa 2 episódios de malária há 10 anos e hipertensão arterial controlada. A mãe faleceu de arritmia aos 48 anos. Exames laboratoriais descartam diabetes mellitus e dislipidemia. Eletrocardiograma apresenta bloqueio de ramo direito. Ecocardiograma mostra dilatação ventricular excêntrica bilateral. Considerando-se a principal hipótese clínica e a fase da doença, qual método laboratorial é indicado para a confirmação diagnóstica nesse caso?","options":[{"id":"A","text":"Exame parasitológico direto por gota espessa.","explanation":""},{"id":"B","text":"Intradermo reação de Montenegro.","explanation":""},{"id":"C","text":"Sorologia por IgG em dois métodos distintos.","explanation":""},{"id":"D","text":"Reação em cadeia da polimerase.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q016","code":"REV-2026.2-Q016","number":16,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q16 · tema a classificar","statement":"Criança de 1 ano e 9 meses, previamente hígida, é levada a uma Unidade Básica de Saúde devido a quadro de rash cutâneo iniciado há 12 horas. Nos últimos três dias, vinha apresentando febre, irritabilidade e inapetência, sem outras manifestações. A febre cessou quando o rash cutâneo surgiu, de maneira repentina, inicialmente no tórax, seguido pelos braços. O exame físico revela paciente em estado geral preservado, ativo, brincando durante avaliação e afebril. Constata-se presença de exantema maculopapular de coloração rosada em face, tronco e extremidades. Palpado linfonodo em região cervical anterior direita, indolor, móvel, fibroelástico, de aproximadamente 0,5 cm. Não há outros achados. Qual é o agente etiológico do caso relatado?","options":[{"id":"A","text":"Vírus Epstein-Barr.","explanation":""},{"id":"B","text":"Parvovírus humano B19.","explanation":""},{"id":"C","text":"Vírus Coxsackie A1.","explanation":""},{"id":"D","text":"Herpes-vírus humano 6.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q017","code":"REV-2026.2-Q017","number":17,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q17 · tema a classificar","statement":"Mulher de 54 anos, com obesidade moderada, procura a emergência clínica de um hospital terciário, relatando dor contínua em hipocôndrio direito, há 72 horas, que se intensificou nas últimas 6 horas, acompanhada de náuseas e febre baixa. Durante a palpação profunda do hipocôndrio direito, apresenta interrupção súbita da inspiração profunda. O hemograma mostra contagem de leucócitos de 12.000 células/mm³ (VR: 4.450 a 10.950 células/mm³), e a ultrassonografia revela vesícula biliar com paredes de 0,8 cm de espessura, múltiplas imagens arredondadas com sombra acústica posterior e colédoco com 0,4 cm de diâmetro. Com base na principal hipótese diagnóstica, qual é a conduta indicada nesse caso?","options":[{"id":"A","text":"Encaminhar para colecistectomia de urgência.","explanation":""},{"id":"B","text":"Indicar descompressão endoscópica das vias biliares.","explanation":""},{"id":"C","text":"Solicitar ressonância magnética de abdome superior.","explanation":""},{"id":"D","text":"Tratar clinicamente com antibióticos e analgésicos.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q018","code":"REV-2026.2-Q018","number":18,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q18 · tema a classificar","statement":"Mulher de 23 anos, G2P0A1, com última menstruação há 8 semanas, é atendida em uma emergência com dor pélvica leve e sangramento vaginal em pequena quantidade. PA 120 x 70 mmHg e FC 82 bpm. Ao exame físico, apresenta-se lúcida e orientada, sem dor à palpação de abdômen e pelve. Tem beta-HCG quantitativo de 1920 mUI/mL na primeira dosagem e 700 mUI/mL na segunda dosagem. Na ultrassonografia transvaginal: ausência de saco gestacional na cavidade uterina; presença de massa anexial esquerda de 2,0 cm com sinal de anel tubário e ausência de batimento cardíaco fetal ou de líquido livre na cavidade pélvica. Qual é a estratégia de manejo indicada nesse caso?","options":[{"id":"A","text":"Orientar beta-HCG quantitativo seriado.","explanation":""},{"id":"B","text":"Indicar procedimento cirúrgico.","explanation":""},{"id":"C","text":"Prescrever o uso de metotrexate.","explanation":""},{"id":"D","text":"Indicar aspiração intrauterina.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q019","code":"REV-2026.2-Q019","number":19,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q19 · tema a classificar","statement":"Uma equipe de Saúde da Família, durante planejamento semestral, identificou um aumento significativo na incidência de obesidade e hipertensão arterial sistêmica na população adscrita. O nutricionista propôs uma ação educativa baseada nas recomendações do Guia alimentar para a população brasileira. O objetivo era impactar positivamente os determinantes sociais da saúde e a redução de doenças crônicas não transmissíveis. Assinale a alternativa que contém a estratégia educativa a ser priorizada pela equipe para enfrentar o problema identificado.","options":[{"id":"A","text":"Estimular a redução do aporte calórico diário, com o uso de produtos diet e light.","explanation":""},{"id":"B","text":"Ensinar a contagem sistemática de calorias, com cálculo de macronutrientes para controle da ingestão energética.","explanation":""},{"id":"C","text":"Promover habilidades culinárias, com o resgate de hábitos regionais, e incentivar o consumo de alimentos in natura.","explanation":""},{"id":"D","text":"Recomendar a exclusão de alimentos processados, como queijos e pães artesanais, e conservar vegetais da dieta regular.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q020","code":"REV-2026.2-Q020","number":20,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q20 · tema a classificar","statement":"Homem de 58 anos, que era residente em território adscrito a uma Unidade de Saúde da Família, vinha sendo acompanhado, há alguns meses, por queixa de dor abdominal recorrente, constipação crônica, anemia normocítica persistente, parestesias e alterações da memória. Era casado, sem filhos, e trabalhava há mais de 20 anos em sua própria oficina de reciclagem de bateria automotiva. Em determinada ocasião, procurou atendimento em uma Unidade Básica de Saúde devido à exacerbação dos sintomas, com forte dor abdominal. O exame físico feito no momento revelou confusão mental e dor difusa à palpação do abdome. O paciente foi, então, encaminhado para o pronto-socorro; porém, nas primeiras 24 horas da internação, evoluiu com insuficiência renal, convulsão, coma e óbito, devido a uma provável intoxicação por chumbo. Qual é o papel da atenção primária em saúde com relação à vigilância do caso?","options":[{"id":"A","text":"Registrar no Sistema de Informação de Agravos de Notificação e comunicar à Vigilância em Saúde do Trabalhador.","explanation":""},{"id":"B","text":"Registrar no Sistema de Informação de Mortalidade e comunicar à Vigilância em Saúde do Trabalhador.","explanation":""},{"id":"C","text":"Registrar no Sistema de Informação de Agravos de Notificação e no Sistema de Informação de Mortalidade.","explanation":""},{"id":"D","text":"Registrar no Sistema de Informação de Agravos de Notificação e acionar a Vigilância Sanitária.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q021","code":"REV-2026.2-Q021","number":21,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q21 · tema a classificar","statement":"Mulher de 30 anos chega ao Centro de Atenção Psicossocial animada, inquieta e falante, andando de um lado para outro, cumprimentando todas as pessoas com sorrisos exagerados e fazendo comentários animados a respeito de coisas aleatórias, emendando os assuntos. O médico que costuma atendê-la percebe que ela está diferente, mais “elétrica” que seu habitual, sendo impossível interrompê-la. As alterações psicopatológicas apresentadas por essa paciente incluem","options":[{"id":"A","text":"humor disfórico, esterotipias vocais e agitação psicomotora.","explanation":""},{"id":"B","text":"humor hipotímico, apragmatismo e afrouxamento de associações.","explanation":""},{"id":"C","text":"humor eutímico, fuga de ideias e avolia.","explanation":""},{"id":"D","text":"humor hipertímico, taquipsiquismo e taquilalia.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q022","code":"REV-2026.2-Q022","number":22,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q22 · tema a classificar","statement":"Homem de 49 anos, com diabetes mellitus tipo 2, em uso irregular de metformina e dapaglifozina, procura uma Unidade de Pronto Atendimento com queixa de poliúria, polidipsia, fadiga e visão turva há 3 dias. Ao exame físico, apresenta-se hemodinamicamente estável, discretamente desidratado, sem sinais de infecção, sem dor abdominal e sem náuseas ou vômitos. Glicemia capilar: 420 mg/dL. Glicemia plasmática confirmatória: 460 mg/dL. Foram realizados exames para avaliação do quadro clínico do paciente, cujos resultados são apresentados na seguinte tabela. Qual é o provável diagnóstico desse paciente?","options":[{"id":"A","text":"Cetoacidose diabética.","explanation":""},{"id":"B","text":"Estado hiperosmolar hiperglicêmico.","explanation":""},{"id":"C","text":"Hiperglicemia não crítica de emergência metabólica.","explanation":""},{"id":"D","text":"Acidose metabólica induzida por medicação.","explanation":""}],"correct_option":"C","needs_image":true},{"id":"revalida_2026_2_q023","code":"REV-2026.2-Q023","number":23,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q23 · tema a classificar","statement":"Menino de 2 anos e 3 meses é levado pela mãe a uma Unidade Básica de Saúde para consulta de rotina. Ela refere palidez progressiva e redução do apetite nos últimos dois meses. O exame físico mostra palidez cutaneomucosa, sem outros achados relevantes. O hemograma mostra os seguintes resultados. A conduta para essa criança é prescrever","options":[{"id":"A","text":"ferro oral em dose terapêutica e orientar adequação alimentar.","explanation":""},{"id":"B","text":"polivitamínico com ferro em dose profilática e manter dieta atual.","explanation":""},{"id":"C","text":"ferro oral em dose profilática e orientar uso de ácido fólico.","explanation":""},{"id":"D","text":"ferro endovenoso e suplementar com vitamina B12.","explanation":""}],"correct_option":"A","needs_image":true},{"id":"revalida_2026_2_q024","code":"REV-2026.2-Q024","number":24,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q24 · tema a classificar","statement":"Homem de 58 anos, no 2º dia de pós-operatório de hemicolectomia esquerda por neoplasia de cólon, apresenta distensão abdominal progressiva, náuseas e vômitos ocasionais. Refere não ter eliminado flatos ou fezes desde o procedimento. Exame físico: paciente em bom estado geral, lúcido, afebril; PA 120 x 80 mmHg; FC 78 bpm. Abdome: globoso, com timpanismo difuso, indolor à palpação, sem massas ou sinais de peritonite; ruídos hidroaéreos diminuídos. A radiografia simples de abdome em pé e deitado mostra distensão difusa de alças de delgado e cólon, sem níveis hidroaéreos. Diante do quadro clínico apresentado, a conduta recomendada nesse momento é","options":[{"id":"A","text":"indicar reintervenção cirúrgica e confecção de colostomia em alça.","explanation":""},{"id":"B","text":"estimular deambulação precoce e considerar progressão de dieta conforme aceitação.","explanation":""},{"id":"C","text":"realizar descompressão colonoscópica e administrar neostigmina sob monitorização cardíaca.","explanation":""},{"id":"D","text":"iniciar nutrição parenteral total e antibioticoterapia de amplo espectro.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q025","code":"REV-2026.2-Q025","number":25,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q25 · tema a classificar","statement":"Mulher de 20 anos procura Unidade de Pronto Atendimento devido a queixa de corrimento vaginal há 7 dias, associado a odor fétido e prurido leve. Refere início recente de dor pélvica hipogástrica, febre não aferida e dispareunia. O exame ginecológico mostra corrimento acinzentado, colo uterino doloroso à mobilização e dor à palpação anexial bilateral. Qual é o tratamento medicamentoso nesse caso, considerando-se o diagnóstico provável?","options":[{"id":"A","text":"Metronidazol, ceftriaxona e doxiciclina.","explanation":""},{"id":"B","text":"Fluconazol, azitromicina e clidamicina.","explanation":""},{"id":"C","text":"Doxiciclina, ceftriaxona e gentamicina.","explanation":""},{"id":"D","text":"Miconazol, metronidazol e azitromicina.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q026","code":"REV-2026.2-Q026","number":26,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q26 · tema a classificar","statement":"Mulher cisgênero de 26 anos, profissional do sexo, comparece a uma Unidade Básica de Saúde para consulta agendada. Relata uso inconsistente de preservativos e manifesta preocupação com o risco de infecção pelo HIV. Nega comorbidades ou uso contínuo de medicações. Realizou teste rápido para HIV há 2 meses em uma ação social, com resultado não reagente, e exames laboratoriais recentes, que mostram função renal preservada. Durante a consulta, a médica de família oferta novos testes rápidos para HIV, sífilis, hepatites B e C, todos não reagentes, e exclui, por anamnese e exame físico, a presença de sinais e sintomas de infecção aguda pelo HIV ou outras infecções sexualmente transmissíveis ativas no momento. Considerando-se o início da prevenção, o manejo da profilaxia pré-exposição (PrEP) para esse caso é prescrevê-la na modalidade","options":[{"id":"A","text":"sob demanda e agendar retorno mensal para teste rápido.","explanation":""},{"id":"B","text":"de uso diário consecutivo e orientar que a proteção ocorrerá em 20 dias.","explanation":""},{"id":"C","text":"sob demanda e aguardar confirmação da sorologia com resultado não reagente.","explanation":""},{"id":"D","text":"de uso diário consecutivo e agendar retorno trimestral para teste rápido.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q027","code":"REV-2026.2-Q027","number":27,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q27 · tema a classificar","statement":"Em uma Unidade Básica de Saúde, foi avaliado o desempenho de um teste rápido de triagem para diabetes mellitus tipo 2 em homens e mulheres, assintomáticos, de 40 a 69 anos, atendidos no território adscrito. A incidência estimada de diabetes nessa população era de 10%, com base em dados locais. O teste rápido foi comparado ao padrão de referência (glicemia de jejum ≥ 126 mg/dL). Os resultados percentuais obtidos estão apresentados na seguinte tabela. Com base na tabela, quais são, respectivamente, o valor e a interpretação clínica para a razão de verossimilhança positiva do teste rápido avaliado?","options":[{"id":"A","text":"0,02 — indica redução na probabilidade de o paciente ter a doença.","explanation":""},{"id":"B","text":"1,12 — demonstra uma alteração mínima e irrelevante na probabilidade de o paciente ter a doença.","explanation":""},{"id":"C","text":"8,00 — apresenta aumento moderado na probabilidade pós-teste de o paciente ter a doença.","explanation":""},{"id":"D","text":"9,00 — confirma o diagnóstico definitivo do diabetes, independentemente da probabilidade do teste.","explanation":""}],"correct_option":"C","needs_image":true},{"id":"revalida_2026_2_q028","code":"REV-2026.2-Q028","number":28,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q28 · tema a classificar","statement":"Homem de 29 anos comparece a uma Unidade Básica de Saúde queixando-se de “sofrimento emocional constante” e “problemas nos relacionamentos”. Relata episódios frequentes de explosões de raiva, sensação de abandono quando os outros não respondem como ele espera e histórico de relações interpessoais intensas e instáveis, com ocorrências de lesões autoprovocadas leves (arranhões em face interna de braços) quando se sente frustrado ou rejeitado. O prontuário revela que o paciente passou por diversos serviços de saúde e abandona os acompanhamentos com frequência. Na consulta, demonstra desconfiança inicial e uma busca intensa por atenção e aprovação da médica. Não há evidências de sintomas psicóticos nem quadro compatível com transtorno de humor. Qual é o transtorno de personalidade identificado nesse caso?","options":[{"id":"A","text":"Paranoide.","explanation":""},{"id":"B","text":"Borderline.","explanation":""},{"id":"C","text":"Dependente.","explanation":""},{"id":"D","text":"Antissocial.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q029","code":"REV-2026.2-Q029","number":29,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q29 · tema a classificar","statement":"Mulher de 67 anos procura unidade de emergência com queixa de fadiga, fraqueza e palpitação, com início há 3 dias. Encontra-se hemodinamicamente estável. Seu eletrocardiograma é apresentado na imagem a seguir. Qual é a conduta imediata para esse caso?","options":[{"id":"A","text":"Realizar cardioversão elétrica.","explanation":""},{"id":"B","text":"Iniciar amiodarona em bolus.","explanation":""},{"id":"C","text":"Indicar anticoagulação.","explanation":""},{"id":"D","text":"Implantar marca-passo temporário.","explanation":""}],"correct_option":"C","needs_image":true},{"id":"revalida_2026_2_q030","code":"REV-2026.2-Q030","number":30,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q30 · tema a classificar","statement":"Adolescente de 13 anos compareceu a uma Unidade Básica de Saúde para avaliação anual de saúde. Encontra-se assintomática. Ao exame físico, apresenta-se em bom estado geral, com PA e FC normais para a idade. A ausculta cardíaca mostra sopro sistólico de baixa intensidade (grau 1+/4+), audível no foco pulmonar, sem irradiação, com timbre suave, que diminui de intensidade quando em posição ortostática. Não há frêmito, nem outros ruídos cardíacos anormais. Quanto a antecedentes pessoais, não relata história de dispneia, dor torácica, síncope ou intolerância aos esforços. Não há antecedentes familiares de cardiopatia ou morte súbita. Considerando-se os dados da paciente, o que sugere o diagnóstico de sopro cardíaco inocente?","options":[{"id":"A","text":"Sopro sistólico de baixa intensidade, sem irradiação e com diminuição em posição ortostática.","explanation":""},{"id":"B","text":"Sopro localizado em foco pulmonar sem irradiação, associado à ausência de sintomas respiratórios.","explanation":""},{"id":"C","text":"Ausência de antecedentes familiares de cardiopatia congênita ou de morte súbita.","explanation":""},{"id":"D","text":"Presença de PA e FC dentro da normalidade para a idade.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q031","code":"REV-2026.2-Q031","number":31,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q31 · tema a classificar","statement":"Menino de 12 anos é levado por seus pais a um pronto-socorro porque se machucou, há 5 dias, com galho de árvore. Os pais relatam que demoraram a buscar atendimento para o filho por morarem em região de difícil acesso. Exame físico: ferimento corto-contuso na face lateral da perna direita, com aproximadamente 12 cm, irregular, com presença de contaminação grosseira da ferida. Os pais afirmam que o paciente tem histórico de atopias e que tomou as vacinas da infância até os 5 anos. O médico indica desbridamento cirúrgico, sob anestesia local infiltrativa, com 20 mL de lidocaína a 2% sem vasoconstritor. Durante o procedimento, o paciente começa a relatar formigamento nos lábios, gosto metálico na boca e zumbido. Em seguida, apresenta crise convulsiva tônico-clônica generalizada. Qual é o diagnóstico provável do quadro apresentado no momento da cirurgia?","options":[{"id":"A","text":"Reação anafilática grave.","explanation":""},{"id":"B","text":"Toxicidade pelo anestésico.","explanation":""},{"id":"C","text":"Paroxismo tetânico.","explanation":""},{"id":"D","text":"Sepse por infecção da ferida.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q032","code":"REV-2026.2-Q032","number":32,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q32 · tema a classificar","statement":"Mulher de 21 anos, G1P0, com 27 semanas e 1 dia de gestação, procura Unidade Básica de Saúde para mostrar o resultado do exame de curva glicêmica (teste oral de tolerância à glicose 75 g), conforme descrito na seguinte tabela. Além de orientação de dieta pobre em carboidrato e atividade física regular, qual a medida imediata deve ser adotada no seguimento do tratamento dessa paciente?","options":[{"id":"A","text":"Solicitar dosagem de insulina.","explanation":""},{"id":"B","text":"Repetir curva glicêmica.","explanation":""},{"id":"C","text":"Solicitar dosagem de HbA1c.","explanation":""},{"id":"D","text":"Monitorar a glicemia capilar.","explanation":""}],"correct_option":"D","needs_image":true},{"id":"revalida_2026_2_q033","code":"REV-2026.2-Q033","number":33,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q33 · tema a classificar","statement":"Mãe leva filha de 6 anos para consulta de puericultura em Unidade Básica de Saúde. A criança tem histórico familiar de hipercolesterolemia (pai e mãe), mas não apresenta comorbidades nem faz uso de medicações. Durante o exame físico, identifica-se IMC na faixa de sobrepeso. Considerando-se as diretrizes brasileiras de dislipidemia e prevenção de aterosclerose, além das orientações sobre mudança de estilo de vida, qual é a conduta indicada nesse caso?","options":[{"id":"A","text":"Solicitar dosagem de lipoproteína A e, se normal, repetir entre 12 e 16 anos de idade.","explanation":""},{"id":"B","text":"Solicitar dosagem de triglicerídeos, colesterol total, HDL-c e LDL-c e, se normais, repetir entre 12 e 16 anos de idade.","explanation":""},{"id":"C","text":"Rastrear a partir dos 9 anos, caso a criança mantenha IMC compatível com sobrepeso ou obesidade.","explanation":""},{"id":"D","text":"Solicitar dosagem de LDL-c e, se alterado, ampliar para perfil lipídico completo e prescrever estatina.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q034","code":"REV-2026.2-Q034","number":34,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q34 · tema a classificar","statement":"A Coordenação de IST/AIDS de um município brasileiro analisou a série histórica de indicadores epidemiológicos relativos à infecção pelo HIV no período de 2019 a 2023. Nesse intervalo, houve ampla expansão da oferta de diagnóstico e implementação de novos protocolos, com medicamentos de maior eficácia e menor toxicidade. A população do município permaneceu estável em aproximadamente 100 mil habitantes. A tabela a seguir apresenta os dados consolidados do período. Considerando-se a relação entre as medidas de frequência e a dinâmica demográfica, a elevação da prevalência da infecção no período analisado é consequência","options":[{"id":"A","text":"da crescente virulência das cepas virais circulantes, indicada pela estabilidade da taxa de incidência.","explanation":""},{"id":"B","text":"do aumento da duração média da doença, resultante da redução da letalidade observada na série.","explanation":""},{"id":"C","text":"da ineficácia das estratégias de prevenção primária, demonstrada pelo acúmulo de casos ativos.","explanation":""},{"id":"D","text":"da variação de exposição de risco da infecção, o que gera diagnósticos superiores à capacidade de resolução do sistema.","explanation":""}],"correct_option":"B","needs_image":true},{"id":"revalida_2026_2_q035","code":"REV-2026.2-Q035","number":35,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q35 · tema a classificar","statement":"Uma equipe da atenção primária à saúde acolhe uma mulher de 42 anos cuja casa foi destruída há 3 dias, após um desastre natural. Ela afirma estar bastante angustiada e desesperançosa, com sono entrecortado e pesadelos. Refere, ainda, choro recorrente, inapetência e dificuldade de concentração. Relata que, apesar de tudo isso, os filhos lhe dão “força para seguir adiante” e nega pensamentos de morte ou ideação suicida. Além de abrigo, alimentação e abastecimento de água, que ações, no âmbito da saúde, devem ser inicialmente oferecidas a essa paciente?","options":[{"id":"A","text":"Realizar escuta ativa, identificando as suas necessidades de saúde, e manter o seguimento na atenção primária à saúde.","explanation":""},{"id":"B","text":"Solicitar relato dos eventos traumáticos, oferecendo visão de futuro otimista, e orientar busca por serviço de urgência se houver piora.","explanation":""},{"id":"C","text":"Prescrever inibidores seletivos da recaptação de serotonina ou benzodiazepínicos e encaminhar a ambulatório especializado.","explanation":""},{"id":"D","text":"Indicar acompanhamento psicológico regular e encaminhar a um centro de atenção psicossocial.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q036","code":"REV-2026.2-Q036","number":36,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q36 · tema a classificar","statement":"Mulher de 23 anos, com diagnóstico de anemia falciforme, procura Unidade de Pronto Atendimento devido à dor em membros inferiores (escala visual analógica = 9), iniciada há 12 horas. Relata crises similares anteriores e nega outros sintomas. Ao ser avaliada, está afebril, hidratada, sem sinais de infecção. Exame físico: PA 112 x 70 mmHg; FC 92 bpm; FR 18 irpm e SatO₂ 97% em ar ambiente. Qual é a conduta medicamentosa imediata para essa paciente?","options":[{"id":"A","text":"Codeína e paracetamol via oral.","explanation":""},{"id":"B","text":"Dipirona intravenosa.","explanation":""},{"id":"C","text":"Tenoxicam intramuscular.","explanation":""},{"id":"D","text":"Morfina intravenosa.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q037","code":"REV-2026.2-Q037","number":37,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q37 · tema a classificar","statement":"Escolar de 5 anos, pesando 20 kg, apresenta queimaduras de 2º e 3º graus que atingem os membros inferiores (ambos integralmente), o tórax e o abdome anteriores. Abaixo o diagrama de Lund-Browder para cálculo da superfície corporal queimada: No caso apresentado, qual a forma correta de administração de Ringer lactato?","options":[{"id":"A","text":"2.820 mL, administrado em 16 horas.","explanation":""},{"id":"B","text":"3.760 mL, administrado em 8 horas.","explanation":""},{"id":"C","text":"1.500 mL, administrado em 2 horas.","explanation":""},{"id":"D","text":"1.000 mL, administrado em 15 a 20 minutos.","explanation":""}],"correct_option":"A","needs_image":true},{"id":"revalida_2026_2_q038","code":"REV-2026.2-Q038","number":38,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q38 · tema a classificar","statement":"Homem de 28 anos é levado pelo SAMU para um hospital de trauma, após ferimento por arma de fogo no hemitórax direito. Apresenta dispneia, dor torácica, pulsos filiformes, FC 128 bpm, FR 32 irpm, PA 90 x 55 mmHg e SpO₂ 89% em ar ambiente. Há assimetria da expansão torácica, macicez à percussão e redução do murmúrio vesicular à direita. A radiografia de tórax evidencia velamento à direita. Diante do quadro, qual é a conduta adequada para o paciente nesse momento?","options":[{"id":"A","text":"Drenagem torácica.","explanation":""},{"id":"B","text":"Toracotomia na sala de emergência.","explanation":""},{"id":"C","text":"Punção torácica de alívio.","explanation":""},{"id":"D","text":"Videotoracoscopia.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q039","code":"REV-2026.2-Q039","number":39,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q39 · tema a classificar","statement":"Gestante de 24 anos, G1P0, com 12 semanas de gestação, procura atendimento médico para mostrar o resultado de teste rápido para HIV realizado na primeira consulta do pré-natal, o qual consta como reagente. Demonstra ansiedade e afirma nunca ter imaginado essa possibilidade. Refere medo de ser julgada e receio de que sua família descubra o diagnóstico. Em atenção aos princípios da comunicação em saúde, da ética médica e do cuidado humanizado, qual é a conduta inicial nesse caso?","options":[{"id":"A","text":"Solicitar a presença de um familiar da paciente e encaminhá-la para o pré-natal de alto risco.","explanation":""},{"id":"B","text":"Acolher a paciente com escuta ativa e fornecer esclarecimentos quanto ao resultado do teste rápido.","explanation":""},{"id":"C","text":"Explicar à paciente o risco de transmissão da doença ao feto e solicitar sorologia para confirmar o diagnóstico.","explanation":""},{"id":"D","text":"Tranquilizar a paciente e iniciar terapia antirretroviral.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q040","code":"REV-2026.2-Q040","number":40,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q40 · tema a classificar","statement":"Mulher de 66 anos, hipertensa, diabética e tabagista, é levada a uma Unidade Básica de Saúde (UBS) por quadro de síncope há 40 minutos, após discussão familiar. Apresenta-se ansiosa, com mal-estar intenso, tontura, náuseas e sudorese, e tem um episódio de vômito na UBS. Relata sensação de desconforto moderado em andar superior do abdome. Nega alergias, etilismo ou uso de drogas ilícitas. Ao exame físico, apresenta-se eupneica, com PA 86 x 53 mmHg, FC 49 bpm e SpO₂ 95% em ar ambiente. O desconforto abdominal não é reproduzível à palpação. Não há outras alterações ao exame físico. A UBS não dispõe de eletrocardiograma ou monitor cardíaco. Além de se acionar o SAMU, a conduta de suporte nesse caso deve incluir","options":[{"id":"A","text":"AAS via oral mastigado.","explanation":""},{"id":"B","text":"isossorbida sublingual.","explanation":""},{"id":"C","text":"omeprazol via oral.","explanation":""},{"id":"D","text":"diazepam via oral.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q041","code":"REV-2026.2-Q041","number":41,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q41 · tema a classificar","statement":"Homem de 68 anos, com quadro de perda de consciência após picada de abelha, é levado a uma Unidade de Pronto Atendimento ainda confuso e com falta de ar. Vem realizando acompanhamento por hipertensão arterial, insuficiência cardíaca de fração de ejeção reduzida e glaucoma. Faz uso de propranolol, enalapril e espironolactona. O exame físico revela: paciente sonolento e confuso (escala de coma de Glasgow 13); presença de estridor inspiratório; PA 76 x 42 mmHg; FC 54 bpm; FR 28 irpm; temperatura axilar 35,9 °C e glicemia capilar 102 mg/dL. Após administração de 0,5 mg de adrenalina intramuscular, o paciente mantém o quadro descrito. Qual é a próxima conduta medicamentosa para o caso?","options":[{"id":"A","text":"Glucagon.","explanation":""},{"id":"B","text":"Atropina.","explanation":""},{"id":"C","text":"Adrenalina.","explanation":""},{"id":"D","text":"Dopamina.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q042","code":"REV-2026.2-Q042","number":42,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q42 · tema a classificar","statement":"Lactente de 5 meses, prematuro de 32 semanas, com antecedente de displasia broncopulmonar, é levado pela mãe a uma Unidade de Pronto Atendimento, com relato de que, há 3 dias, iniciou quadro de coriza e tosse, com piora progressiva do estado geral e dificuldade para mamar nas últimas 24 horas. O exame físico mostra: FR 65 irpm; tiragem subcostal, sibilos e roncos à ausculta; SpO₂ 90% em ar ambiente. A conduta inicial nesse caso consiste em","options":[{"id":"A","text":"oxigenoterapia e amoxicilina oral.","explanation":""},{"id":"B","text":"hidratação endovenosa e suporte ventilatório.","explanation":""},{"id":"C","text":"salbutamol inalatório e corticoide sistêmico.","explanation":""},{"id":"D","text":"fisioterapia respiratória e dexametasona intramuscular.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q043","code":"REV-2026.2-Q043","number":43,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q43 · tema a classificar","statement":"Homem de 50 anos, pedreiro, foi atendido em ambulatório de especialidade, há 4 meses, com queixa de lombociatalgia e dificuldade de exercer atividades laborais. Realizou ressonância magnética da coluna lombar, que evidenciou hérnia discal no nível L4-L5. Antes da data do retorno para mostrar os resultados dos exames, apresentou perda de sensibilidade no períneo, anestesia em sela e incontinência urinária. Devido a esses novos sintomas, procurou uma Unidade de Pronto Atendimento. Considerando-se o quadro clínico descrito, qual é a conduta adequada para esse paciente?","options":[{"id":"A","text":"Antecipar retorno ao ambulatório de especialidade.","explanation":""},{"id":"B","text":"Indicar tratamento com corticoide epidural.","explanation":""},{"id":"C","text":"Internar com prescrição de analgésicos associado a relaxantes musculares.","explanation":""},{"id":"D","text":"Encaminhar ao serviço de emergência para avaliar indicação cirúrgica.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q044","code":"REV-2026.2-Q044","number":44,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q44 · tema a classificar","statement":"Gestante de 24 anos, com 11 semanas de gestação, comparece à Unidade Básica de Saúde para consulta de pré-natal, trazendo os resultados de exames solicitados em consulta anterior. Está sem queixas no momento. Entre os exames apresentados, observa-se sorologia para toxoplasmose com IgG reagente e IgM não reagente. O resultado desse exame sorológico de toxoplasmose indica","options":[{"id":"A","text":"susceptibilidade.","explanation":""},{"id":"B","text":"infecção aguda.","explanation":""},{"id":"C","text":"imunidade.","explanation":""},{"id":"D","text":"soroconversão recente.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q045","code":"REV-2026.2-Q045","number":45,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q45 · tema a classificar","statement":"Menino de 1 ano é levado pelos pais para consulta de puericultura em Unidade Básica de Saúde. Eles referem preocupação com a vacina tríplice viral e informam que a criança apresentou reações leves após receber aplicações de outras vacinas. Relatam também que, pesquisando sobre o tema em redes sociais, assistiram a vídeos que associavam a vacina tríplice viral ao desenvolvimento do transtorno do espectro autista (TEA). Receosos, hesitam em imunizar o filho. Qual é a abordagem a ser realizada com esses pais?","options":[{"id":"A","text":"Explicar que há baixa ocorrência de TEA em crianças vacinadas e encaminhar paciente para a atualização vacinal.","explanation":""},{"id":"B","text":"Orientar sobre a importância das vacinas e reforçar a superioridade de seus benefícios em relação à possibilidade de TEA.","explanation":""},{"id":"C","text":"Pesquisar sintomas preditores de TEA na criança e, em caso de resultado negativo, continuar o protocolo de vacinação segura.","explanation":""},{"id":"D","text":"Acolher a preocupação dos familiares e fornecer informações sobre a ausência de associação entre TEA e vacinas.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q046","code":"REV-2026.2-Q046","number":46,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q46 · tema a classificar","statement":"Homem de 71 anos, tabagista, hipertenso, em uso de bloqueador de canal de cálcio, dá entrada em emergência com quadro de dor retroesternal em queimação, com início há 1 hora, após ter feito uma refeição farta. Exame físico: paciente hemodinamicamente estável; PA 160 x 90 mmHg; FC 72 bpm. Qual é a conduta imediata para esse paciente?","options":[{"id":"A","text":"Indicar ecocardiograma transesofágico.","explanation":""},{"id":"B","text":"Solicitar eletrocardiograma e marcadores de necrose miocárdica.","explanation":""},{"id":"C","text":"Dosar D-dímero e realizar angiotomografia de tórax.","explanation":""},{"id":"D","text":"Realizar endoscopia digestiva alta.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q047","code":"REV-2026.2-Q047","number":47,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q47 · tema a classificar","statement":"Menina de 10 anos é encaminhada para avaliação especializada por perda de peso progressiva nos últimos 10 meses. A mãe relata que a criança, após engasgar com carne, passou a recusar alimentos sólidos e a apresentar episódios de refeições prolongadas com vômitos, quando há insistência para alimentar-se, além de medo de “passar mal” em ambiente escolar ou em eventos sociais. Aceita alimentos pastosos. Nega dor abdominal, diarreia, febre ou infecções. Sono e desempenho escolar estão preservados. O desenvolvimento neuropsicomotor é adequado para a idade. O exame físico mostra: escore Z igual a peso –3; estatura entre –1 e –2; IMC entre –2 e –3. Foram excluídas causas orgânicas. A principal hipótese diagnóstica nesse caso é","options":[{"id":"A","text":"transtorno dismórfico corporal.","explanation":""},{"id":"B","text":"anorexia nervosa.","explanation":""},{"id":"C","text":"transtorno alimentar restritivo evitativo.","explanation":""},{"id":"D","text":"seletividade alimentar típica.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q048","code":"REV-2026.2-Q048","number":48,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q48 · tema a classificar","statement":"Homem de 32 anos, vítima de acidente motociclístico envolvendo colisão contra poste, com uso de capacete, é atendido no local do acidente por equipe avançada do SAMU. Está consciente e conversando, com sinais vitais estáveis. Apresenta escoriações no braço e no ombro esquerdos, ferimento corto-contuso de 3 cm em região clavicular esquerda, com exposição de fragmento ósseo pela ferida. Há ausência de flexão do punho e dos dedos da mão esquerda, com anestesia em região medial do antebraço. Pulsos palpáveis. É realizada a limpeza do ferimento clavicular. Nessa situação, qual outra conduta deve ser realizada no local do acidente?","options":[{"id":"A","text":"Imobilizar com curativo.","explanation":""},{"id":"B","text":"Reduzir fratura da clavícula.","explanation":""},{"id":"C","text":"Realizar tração do membro superior.","explanation":""},{"id":"D","text":"Alinhar com tala moldável.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q049","code":"REV-2026.2-Q049","number":49,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q49 · tema a classificar","statement":"Mulher de 23 anos, G3P3, sem comorbidades, procura atendimento em Unidade Básica de Saúde, manifestando forte desejo de ser submetida à laqueadura tubária. De acordo com a lei de planejamento familiar, qual é a conduta inicial do profissional de saúde nesse caso?","options":[{"id":"A","text":"Informar que a situação da paciente está em desacordo com os critérios legais pertinentes.","explanation":""},{"id":"B","text":"Orientar que é necessária a autorização do cônjuge para a realização do procedimento.","explanation":""},{"id":"C","text":"Oferecer à paciente informações a respeito de outros métodos anticoncepcionais.","explanation":""},{"id":"D","text":"Encaminhar a paciente para a realização do procedimento em questão.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q050","code":"REV-2026.2-Q050","number":50,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q50 · tema a classificar","statement":"Homem de 34 anos, tabagista, sedentário, com IMC 43 kg/m² e assintomático, comparece a uma consulta em Unidade Básica de Saúde relatando que seu pai foi diagnosticado com câncer de cólon aos 53 anos. O paciente demonstra preocupação com a doença. Considerando-se o rastreamento do câncer colorretal desse paciente pelo SUS, a conduta nesse caso é solicitar colonoscopia","options":[{"id":"A","text":"na consulta atual.","explanation":""},{"id":"B","text":"a partir dos 43 anos.","explanation":""},{"id":"C","text":"a partir dos 50 anos.","explanation":""},{"id":"D","text":"se a pesquisa de sangue oculto tiver resultado positivo.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q051","code":"REV-2026.2-Q051","number":51,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q51 · tema a classificar","statement":"Um homem de 42 anos foi admitido em uma Unidade de Terapia Intensiva (UTI) com história de provável intoxicação exógena. Ele havia sido encontrado desacordado em sua residência, com sialorreia intensa e broncoespasmo. Exame físico: FC 38 bpm; PA 116 x 64 mmHg; SatO₂ 83% em ar ambiente; escala de coma de Glasgow 3 e glicemia capilar 70 mg/dL. Optou-se por intubação orotraqueal e instalação de ventilação mecânica invasiva. Na UTI, o paciente apresentava: pupilas puntiformes; roncos e sibilos inspiratórios e expiratórios à ausculta pulmonar; secreção clara e abundante à aspiração de vias aéreas; grande quantidade de resíduo gástrico à sondagem gástrica; boa diurese por sonda vesical de demora e ausência de febre. Foi realizada lavagem gástrica, utilizando-se carvão ativado por 24 horas, e iniciou-se suporte com atropina intravenosa, em bomba de infusão contínua. Qual foi o provável agente da intoxicação desse paciente?","options":[{"id":"A","text":"Organofosforado.","explanation":""},{"id":"B","text":"Benzodiazepínico.","explanation":""},{"id":"C","text":"Sulfonilureia.","explanation":""},{"id":"D","text":"Antidepressivo tricíclico.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q052","code":"REV-2026.2-Q052","number":52,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q52 · tema a classificar","statement":"Menina de 4 anos é levada a uma Unidade Básica de Saúde pela mãe, que relata o aparecimento de lesões avermelhadas e com crostas amareladas na região periorbital, labial e nasal da criança há cerca de 5 dias. A mãe refere que as lesões começaram como pequenas bolhas que se romperam facilmente, liberando um líquido amarelado, com prurido associado. Nega febre, prostração ou demais queixas. Exame físico: sem alterações, exceto a pele da face, conforme a seguinte imagem. O diagnóstico provável para o caso é","options":[{"id":"A","text":"celulite.","explanation":""},{"id":"B","text":"impetigo.","explanation":""},{"id":"C","text":"ectima.","explanation":""},{"id":"D","text":"herpes.","explanation":""}],"correct_option":"B","needs_image":true},{"id":"revalida_2026_2_q053","code":"REV-2026.2-Q053","number":53,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q53 · tema a classificar","statement":"Recém-nascido a termo, masculino, Apgar 9/9, peso, comprimento e perímetro cefálico adequados para idade gestacional. Ultrassom morfológico com polidrâminio. Logo após o nascimento, evoluiu com salivação excessiva. Realizada aspiração da secreção com melhora da saturação, sem necessidade de oxigenioterapia. Ausência de sinais de desconforto respiratório; murmúrio vesicular presente bilateralmente com roncos de transmissão difusos; abdome escavado e extremidades bem perfundidas. Realizada passagem de sonda orogástrica com dificuldade na progressão após a introdução de 10 cm. Solicitada radiografia com contraste iodado (imagem a seguir). Com base no quadro clínico, trata-se de qual tipo de atresia?","options":[{"id":"A","text":"Esofágica.","explanation":""},{"id":"B","text":"Gástrica.","explanation":""},{"id":"C","text":"Duodenal.","explanation":""},{"id":"D","text":"Intestinal.","explanation":""}],"correct_option":"A","needs_image":true},{"id":"revalida_2026_2_q054","code":"REV-2026.2-Q054","number":54,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q54 · tema a classificar","statement":"Mulher, G2P1, assintomática, com história prévia de prematuridade, comparece a uma consulta de pré-natal para mostrar os seguintes resultados de ultrassonografia de 22 semanas: feto vivo, com exame morfológico normal e colo uterino medindo 20 mm. Diante desses resultados, qual é o manejo para o caso?","options":[{"id":"A","text":"Indicar o uso de indometacina até 32 semanas de gestação.","explanation":""},{"id":"B","text":"Prescrever nifedipina e manter até 30 semanas de gestação.","explanation":""},{"id":"C","text":"Prescrever betametasona e repetir o exame com 30 semanas de gestação.","explanation":""},{"id":"D","text":"Indicar progesterona natural e manter até 36 semanas de gestação.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q055","code":"REV-2026.2-Q055","number":55,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q55 · tema a classificar","statement":"Homem de 74 anos comparece a uma Unidade Básica de Saúde para consulta. Mora sozinho e tem como renda o Benefício de Prestação Continuada. Relata que, há 6 meses, sente dor e queimação em ambos os pés, de moderada intensidade, com predomínio noturno, associada a parestesias em “bota”, sem alívio com analgésicos simples. Tem diagnóstico de diabetes mellitus tipo 2 há 18 anos, em uso de metformina e insulina NPH em esquema basal. Não há evidência de cardiopatia associada. A hemoglobina glicada se mantém estável em 6,5% e a taxa de filtração glomerular é 75 mL/min/1,73m². O eletrocardiograma é normal. Ao exame físico, deambula sem dificuldade e evidencia-se hipoestesia tátil e vibratória em padrão distal simétrico, em “bota”, com pulsos distais palpáveis. Não há lesões cutâneas nos membros inferiores. Qual é a medicação de primeira linha para o manejo da dor nesse paciente?","options":[{"id":"A","text":"Carbamazepina.","explanation":""},{"id":"B","text":"Ibuprofeno.","explanation":""},{"id":"C","text":"Amitriptilina.","explanation":""},{"id":"D","text":"Tramadol e paracetamol.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q056","code":"REV-2026.2-Q056","number":56,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q56 · tema a classificar","statement":"Em uma Unidade Básica de Saúde (UBS), a equipe local, preocupada com a alta prevalência de hipertensão arterial sistêmica (HAS) entre os pacientes, decidiu realizar um estudo epidemiológico para investigar possíveis fatores de risco associados à doença. Os pesquisadores selecionaram cerca de 50 pacientes com diagnóstico recente de HAS e 80 pacientes sem a doença, pareados por idade e sexo, que frequentavam a mesma UBS. Com base em entrevistas e em revisão de prontuários, foram coletadas informações sobre histórico familiar de HAS, nível de atividade física e padrão alimentar desses pacientes nos últimos 5 anos. Qual foi o tipo de estudo realizado nesse caso?","options":[{"id":"A","text":"Caso-controle.","explanation":""},{"id":"B","text":"Coorte.","explanation":""},{"id":"C","text":"Ecológico.","explanation":""},{"id":"D","text":"Série temporal.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q057","code":"REV-2026.2-Q057","number":57,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q57 · tema a classificar","statement":"Estudante de Psicologia de 22 anos, de origem Guarani Kaiowá, cometeu suicídio. Pessoas de sua aldeia atribuíram o fato a um suposto enfeitiçamento, justificando que isso teria feito com que ela perdesse o discernimento. Uma equipe de saúde foi acionada para lidar com essa situação. Nesse caso, qual é a abordagem adequada a ser realizada pela equipe de saúde?","options":[{"id":"A","text":"Participar ativamente dos rituais religiosos e de luto próprios da comunidade, para atuar com prontidão caso algum membro da comunidade apresente intenso sofrimento.","explanation":""},{"id":"B","text":"Compreender a crença de enfeitiçamento, mas sem estimulá-la, acolhendo os membros da etnia e orientando sobre sinais de risco a serem observados.","explanation":""},{"id":"C","text":"Acolher as famílias enlutadas, respeitando seus rituais funerários e evitando falar sobre suicídio, visto que a menção a esse tema poderia suscitar novas tentativas.","explanation":""},{"id":"D","text":"Explicar, de maneira objetiva, o que são transtornos mentais e o que é transtorno depressivo maior, para evitar interpretações místicas e ritualísticas do adoecimento.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q058","code":"REV-2026.2-Q058","number":58,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q58 · tema a classificar","statement":"Homem de 40 anos, etilista crônico, procura a unidade de emergência queixando-se de distensão abdominal há 2 dias e náuseas eventualmente acompanhadas de vômitos. Ao exame físico: temperatura axilar aferida de 38,2 °C; mucosas levemente descoradas e anictéricas; aranhas vasculares no tronco; abdome distendido com circulação colateral; sinal de piparote positivo e baço palpável a 3 cm do rebordo costal esquerdo. Qual é a conduta imediata para esse quadro clínico?","options":[{"id":"A","text":"Solicitar hemocultura.","explanation":""},{"id":"B","text":"Realizar paracentese.","explanation":""},{"id":"C","text":"Prescrever antibioticoterapia empírica.","explanation":""},{"id":"D","text":"Iniciar diurético poupador de potássio.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q059","code":"REV-2026.2-Q059","number":59,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q59 · tema a classificar","statement":"Menino de 8 anos é levado a um ambulatório de pediatria com queixa de febre persistente há 3 semanas, associada a palidez progressiva, emagrecimento e aparecimento de petéquias nos membros inferiores. A mãe relata que a criança tem se queixado de dores em membros inferiores e astenia. O exame físico mostra: palidez cutâneo-mucosa; petéquias difusas e hepatoesplenomegalia. O hemograma revela os resultados apresentados na tabela a seguir. Nesse caso, a principal hipótese diagnóstica é","options":[{"id":"A","text":"anemia aplásica.","explanation":""},{"id":"B","text":"leucemia linfoblástica aguda.","explanation":""},{"id":"C","text":"púrpura trombocitopênica imunológica.","explanation":""},{"id":"D","text":"calazar.","explanation":""}],"correct_option":"B","needs_image":true},{"id":"revalida_2026_2_q060","code":"REV-2026.2-Q060","number":60,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q60 · tema a classificar","statement":"Criança de 5 anos é levada a um pronto-socorro após sofrer acidente automobilístico grave, com rebaixamento do nível de consciência, respiração irregular e sinais de comprometimento respiratório, sem sinais de sangramento ativo externo. É indicada obtenção de via aérea eficaz e definitiva. Nesse caso, a particularidade anatômica a ser considerada para a realização de procedimento seguro é o fato de que crianças dessa idade, em comparação com adultos, apresentam","options":[{"id":"A","text":"língua proporcionalmente menor.","explanation":""},{"id":"B","text":"anel cricofaríngeo relativamente mais largo.","explanation":""},{"id":"C","text":"laringe mais baixa e anterior.","explanation":""},{"id":"D","text":"epiglote mais anteriorizada e rígida.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q061","code":"REV-2026.2-Q061","number":61,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q61 · tema a classificar","statement":"Uma paciente de 46 anos, sem comorbidades e assintomática, procura Unidade Básica de Saúde para mostrar resultado de exame realizado para prevenção do câncer de colo uterino: teste de DNA-HPV oncogênico positivo para HPV 51. Informa ter realizado citologia oncótica há 1 ano, sem alterações. Qual é a conduta inicial indicada nesse caso?","options":[{"id":"A","text":"Repetir o teste de DNA-HPV oncogênico.","explanation":""},{"id":"B","text":"Solicitar citologia reflexa.","explanation":""},{"id":"C","text":"Encaminhar para colposcopia.","explanation":""},{"id":"D","text":"Indicar vacina contra o HPV.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q062","code":"REV-2026.2-Q062","number":62,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q62 · tema a classificar","statement":"O Ministério da Saúde lançou, em 2025, os novos indicadores do componente de qualidade do cofinanciamento federal da atenção primária à saúde no SUS. Considerando-se os novos indicadores de cuidado na gestação e puerpério, é necessário garantir a realização","options":[{"id":"A","text":"de pelo menos um exame de ultrassonografia obstétrica durante a gestação.","explanation":""},{"id":"B","text":"dos testes para sífilis, HIV e hepatites B e C no 1º trimestre da gestação.","explanation":""},{"id":"C","text":"da primeira consulta de pré-natal antes da 20ª semana da gestação.","explanation":""},{"id":"D","text":"de pelo menos quatro consultas médicas de pré-natal.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q063","code":"REV-2026.2-Q063","number":63,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q63 · tema a classificar","statement":"Uma equipe técnica do Ministério da Saúde está avaliando os efeitos da redução do ponto de corte da medida de PA sistólica de 130 mmHg para 120 mmHg para o diagnóstico de hipertensão arterial (HA). Considerando-se as mudanças nos valores de referência, o que se espera em relação ao diagnóstico de HA?","options":[{"id":"A","text":"Aumento na detecção da HA e redução na frequência de falsos positivos.","explanation":""},{"id":"B","text":"Aumento na detecção da HA e aumento na frequência de falsos positivos.","explanation":""},{"id":"C","text":"Redução na detecção da HA e redução na frequência de falsos positivos.","explanation":""},{"id":"D","text":"Redução na detecção da HA e aumento na frequência de falsos positivos.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q064","code":"REV-2026.2-Q064","number":64,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q64 · tema a classificar","statement":"Homem de 60 anos, sem emprego formal, está em acompanhamento em um Centro de Atenção Psicossocial (CAPS) por esquizofrenia. Nos últimos meses, retomou uso de álcool, isolou-se mais e foi visto pelos vizinhos diversas vezes embriagado, em casa, falando sozinho. Apresenta dificuldades de pagar o aluguel, de comprar alimentos e medicamentos da mãe de 80 anos, com quem habita. Considerando-se a composição da rede de atenção psicossocial, quais pontos de atenção, além do CAPS, são apropriados para a articulação do cuidado desse paciente?","options":[{"id":"A","text":"Unidade de Pronto Atendimento; atenção primária à saúde; e centros de convivência e cultura.","explanation":""},{"id":"B","text":"Serviço móvel de urgência; serviços residenciais terapêuticos; e centro de orientação e aconselhamento.","explanation":""},{"id":"C","text":"Unidade de acolhimento; centro de referência em assistência social; e unidades ambulatoriais especializadas.","explanation":""},{"id":"D","text":"Equipe de consultório na rua; núcleos de apoio à saúde da família; e serviço de atenção domiciliar.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q065","code":"REV-2026.2-Q065","number":65,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q65 · tema a classificar","statement":"Homem de 30 anos, sem comorbidades prévias, procura Unidade Básica de Saúde devido à lesão pruriginosa em região da panturrilha direita, com 3 semanas de evolução. O exame físico mostra lesão anular de cerca de 3 cm de diâmetro, com bordas eritematosas, elevadas e descamativas, com clareamento central. Qual medicamento deve ser prescrito para o tratamento dessa lesão?","options":[{"id":"A","text":"Cefalexina oral.","explanation":""},{"id":"B","text":"Clotrimazol tópico.","explanation":""},{"id":"C","text":"Hidrocortisona tópica.","explanation":""},{"id":"D","text":"Ivermectina oral.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q066","code":"REV-2026.2-Q066","number":66,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q66 · tema a classificar","statement":"Menina de 2 anos apresenta tosse, coriza e obstrução nasal há 24 horas. Há 1 hora, apresentou quadro convulsivo tônico-clônico generalizado, com duração de 2 minutos, e foi levada ao pronto atendimento. Não há relato de convulsão anterior, mas a mãe refere histórico de crise convulsiva febril em irmão mais velho. Os exames mostram: temperatura axilar 38,7 °C; exame neurológico sem alterações e ausência de sinais meníngeos. A conduta adequada para esse caso, após medicar com antitérmico, é","options":[{"id":"A","text":"internar a paciente e coletar líquido cefalorraquidiano.","explanation":""},{"id":"B","text":"solicitar tomografia de crânio e indicar acompanhamento especializado.","explanation":""},{"id":"C","text":"orientar a família e indicar acompanhamento ambulatorial.","explanation":""},{"id":"D","text":"internar a paciente e realizar eletroencefalograma.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q067","code":"REV-2026.2-Q067","number":67,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q67 · tema a classificar","statement":"Homem de 22 anos, vítima de atropelamento, foi levado pelo suporte avançado do SAMU a uma emergência terciária de trauma, onde chegou em prancha rígida, com colar cervical e com queixa de dor em andar inferior de abdome. Avaliação inicial: paciente consciente; contactante; descorado 2+/4+; FC 120 bpm; FR 24 irpm; PA 80 x 60 mmHg; abdome plano, normotenso, doloroso à palpação profunda em andar inferior; descompressão brusca negativa; bacia instável e hematoma em região escrotal. Foram realizadas: medidas de estabilização na sala de emergência; ultrassonografia FAST, cujo resultado foi negativo para líquido livre abdominal; e radiografia da pelve, conforme a seguinte figura. Após, foi aplicada cinta pélvica, o que resultou em estabilização mecânica do anel pélvico, com fechamento do quadril. Nesse caso, mantendo-se um quadro de hipotensão, qual é a próxima conduta a ser realizada?","options":[{"id":"A","text":"Angiografia com embolização.","explanation":""},{"id":"B","text":"Laparotomia exploradora.","explanation":""},{"id":"C","text":"Estabilização cirúrgica do quadril.","explanation":""},{"id":"D","text":"Tomografia de abdome e pelve.","explanation":""}],"correct_option":"C","needs_image":true},{"id":"revalida_2026_2_q068","code":"REV-2026.2-Q068","number":68,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q68 · tema a classificar","statement":"Mulher de 72 anos procura atendimento em Unidade Básica de Saúde com queixas de dores na coluna lombar e histórico de fratura de fêmur após ter sofrido queda da própria altura há 2 anos. É hipertensa, faz uso de hidroclorotiazida e teve menopausa há 22 anos. Não usa nenhum outro medicamento nem fez uso de terapia hormonal. Realizou densitometria óssea recentemente, que indicou um alto risco para fraturas. A paciente não possui história de doenças secundárias associadas à osteoporose nem doenças crônicas, além da hipertensão arterial sistêmica. Não apresenta queixas relacionadas à intolerância gastrointestinal ou à dificuldade de deglutição. Iniciou uso de vitamina D e cálcio via oral. Com base no protocolo clínico nacional para osteoporose, qual é a opção inicial de tratamento medicamentoso?","options":[{"id":"A","text":"Bisfosfonato.","explanation":""},{"id":"B","text":"Estrogênio conjugado.","explanation":""},{"id":"C","text":"Teriparatida.","explanation":""},{"id":"D","text":"Romosozumabe.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q069","code":"REV-2026.2-Q069","number":69,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q69 · tema a classificar","statement":"Mulher de 34 anos, em consulta, relata ao médico de família tristeza, insônia e medo constante. Revela estar, há anos, em relacionamento abusivo que envolve agressões psicológicas, manipulação financeira e episódios recentes de violência física cometida pelo parceiro. Afirma não desejar romper imediatamente o relacionamento por preocupação quanto à sua segurança e à possibilidade de agravamento de sua situação financeira. Considerando-se o planejamento de ações e intervenções centradas na singularidade da pessoa assistida, são condutas adequadas nessa situação","options":[{"id":"A","text":"iniciar tratamento farmacológico, encaminhar paciente para acompanhamento especializado em saúde da mulher e denunciar parceiro à delegacia de proteção à mulher.","explanation":""},{"id":"B","text":"elaborar plano terapêutico com avaliação de risco junto à equipe multiprofissional, fortalecer a rede de apoio e notificar caso à vigilância epidemiológica.","explanation":""},{"id":"C","text":"elaborar plano terapêutico farmacológico, encaminhar paciente para centro de apoio psicossocial e solicitar medida protetiva junto à defensoria pública.","explanation":""},{"id":"D","text":"indicar o acolhimento em casa abrigo como intervenção protetiva, ofertar sorologias para rastreio de IST e notificar caso à rede de atenção psicossocial do município.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q070","code":"REV-2026.2-Q070","number":70,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q70 · tema a classificar","statement":"Em reunião de equipe de saúde da família, discute-se o caso de uma idosa diabética, com locomoção reduzida, que apresenta episódios de hipoglicemia por dificuldade de compreensão do esquema de uso da insulina. A paciente tem 8 filhos, porém reside com apenas uma filha, que trabalha fora o dia todo. Qual ação inicial a equipe deve desenvolver nesse caso?","options":[{"id":"A","text":"Realizar aplicação diária da insulina, na unidade de saúde.","explanation":""},{"id":"B","text":"Solicitar vaga em instituição de longa permanência.","explanation":""},{"id":"C","text":"Realizar a articulação do cuidado com a comunidade.","explanation":""},{"id":"D","text":"Substituir a insulina por hipoglicemiante oral.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q071","code":"REV-2026.2-Q071","number":71,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q71 · tema a classificar","statement":"Homem de 30 anos procurou uma Unidade Básica de Saúde pela primeira vez com o objetivo de reduzir o consumo de crack. Nega uso diário, mas afirma que há momentos em que “engata” 3 dias de uso. Após, consegue ficar semanas sem utilizar, mas recai na sequência. Depois do último uso continuado por 3 dias, não retornou para casa e decidiu buscar ajuda. Considerando-se as recomendações atuais dos Ministérios da Saúde e da Justiça, qual é a conduta inicial para esse paciente?","options":[{"id":"A","text":"Internação hospitalar com abstinência total, com vistas a cessar os efeitos nocivos do consumo.","explanation":""},{"id":"B","text":"Encaminhamento a uma comunidade terapêutica, para acolhimento, devido ao padrão de uso apresentado.","explanation":""},{"id":"C","text":"Realização de ações voltadas à redução de danos, para minimizar problemas secundários ao consumo.","explanation":""},{"id":"D","text":"Prescrição de psicofármaco, uma vez que há medicamentos padronizados para o tratamento.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q072","code":"REV-2026.2-Q072","number":72,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q72 · tema a classificar","statement":"Adolescente de 15 anos comparece à Unidade de Pronto Atendimento com queixa de mialgia, mal-estar e cansaço, iniciados há 1 semana, quadro que evoluiu, há 3 dias, com febre, dor de garganta e odinofagia. Exame físico: amígdalas hiperemiadas, com exsudato bilateral e linfoadenomegalia dolorosa em região cervical posterior bilateral de até 2 cm de diâmetro. É indicado o uso de sintomáticos, além de repouso e observação. Após 24 horas, não tem mais febre, porém apresenta erupção exantemática macular na face, no abdome e na região torácica. Qual é o diagnóstico provável para esse caso clínico?","options":[{"id":"A","text":"Amigdalite bacteriana.","explanation":""},{"id":"B","text":"Infecção pelo vírus Epstein-Barr.","explanation":""},{"id":"C","text":"Reação alérgica ao antitérmico.","explanation":""},{"id":"D","text":"Rinofaringite.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q073","code":"REV-2026.2-Q073","number":73,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q73 · tema a classificar","statement":"Lactente de 1 ano e 4 meses, com calendário vacinal atualizado até os 12 meses, é levada a uma Unidade Básica de Saúde para atualização vacinal. A mãe relata que a criança está em acompanhamento com a nefrologia pediátrica devido à síndrome nefrótica corticossensível. A paciente faz uso de prednisolona em dose imunossupressora há 5 semanas e, no momento, encontra-se assintomática. Considerando-se o calendário vacinal recomendado pelo Ministério da Saúde e a condição clínica da criança, a orientação adequada a ser fornecida pelo médico é","options":[{"id":"A","text":"adiar a vacinação até a suspensão do corticoide.","explanation":""},{"id":"B","text":"adiar a aplicação da vacina tetraviral e aplicar as demais.","explanation":""},{"id":"C","text":"aplicar a vacina contra hepatite A e adiar as demais.","explanation":""},{"id":"D","text":"aplicar todas as vacinas indicadas para a faixa etária.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q074","code":"REV-2026.2-Q074","number":74,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q74 · tema a classificar","statement":"Paciente de 65 anos, em acompanhamento em Unidade Básica de Saúde, retorna para sua consulta anual e relata piora de sintomas do trato urinário inferior, como jato urinário fraco, disúria e noctúria. O exame de toque evidencia próstata aumentada, de consistência elástica e superfície lisa. O PSA total (antígeno prostático específico), realizado há 2 semanas, revela o valor de 6,5 ng/mL (VR: até 4,0 ng/mL). Qual exame deve ser solicitado para comprovar a especificidade diagnóstica nesse caso?","options":[{"id":"A","text":"PSA fração total e livre.","explanation":""},{"id":"B","text":"Ultrassonografia transretal.","explanation":""},{"id":"C","text":"Tomografia contrastada de pelve.","explanation":""},{"id":"D","text":"Biópsia transretal de próstata.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q075","code":"REV-2026.2-Q075","number":75,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q75 · tema a classificar","statement":"Mulher de 28 anos, com ciclos menstruais regulares, comparece a uma Unidade de Pronto Atendimento apresentando dor pélvica iniciada há 2 dias e localizada na fossa ilíaca direita. Nega febre, corrimento vaginal ou outros sintomas associados. Refere data da última menstruação há 16 dias e uso regular de preservativo masculino nas relações sexuais. O exame físico mostra dor à palpação superficial na fossa ilíaca direita, sem sinais de irritação peritoneal e sem outras alterações. Foi realizada ultrassonografia transvaginal, que revelou imagem medindo 2,5 cm no ovário direito, com componente cístico central, parede espessada e regular, ecos internos avasculares e vascularização periférica, conforme a imagem a seguir. Com base nos achados da ultrassonografia e no contexto clínico descrito, a hipótese diagnóstica mais provável é cisto","options":[{"id":"A","text":"paraovariano.","explanation":""},{"id":"B","text":"folicular.","explanation":""},{"id":"C","text":"hemorrágico.","explanation":""},{"id":"D","text":"lúteo.","explanation":""}],"correct_option":"D","needs_image":true},{"id":"revalida_2026_2_q076","code":"REV-2026.2-Q076","number":76,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q76 · tema a classificar","statement":"Menino de 9 anos é levado a uma Unidade Básica de Saúde para continuidade do acompanhamento de transtorno de déficit de atenção e hiperatividade (TDAH). Há prejuízos acadêmicos e sociais significativos refratários às intervenções pedagógicas e comportamentais isoladas. A criança é ativa, joga futebol sem cansaço desproporcional e nega síncope, dor no peito ou palpitações. O pai é hipertenso e a avó materna faleceu de infarto aos 68 anos. Não há relato de morte súbita em familiares jovens, arritmias hereditárias ou surdez congênita. Exame físico sem alterações. Nesse caso, a conduta inicial é","options":[{"id":"A","text":"investigar condições cardiológicas com exames complementares.","explanation":""},{"id":"B","text":"prescrever metilfenidato e monitorar sinais vitais.","explanation":""},{"id":"C","text":"reaplicar escalas de avaliação neuropsicológica.","explanation":""},{"id":"D","text":"instituir atomoxetina e orientar sobre eventos adversos.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q077","code":"REV-2026.2-Q077","number":77,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q77 · tema a classificar","statement":"Em maio de 2024, aconteceram inundações devastadoras no Rio Grande do Sul (RS), que afetaram 478 municípios e mais de 2 milhões de pessoas, segundo dados de 2025 do Boletim da Defesa Civil do RS. Várias famílias ficaram desalojadas. Além disso, houve contaminação hídrica e desabastecimento da rede assistencial. Diante do quadro apresentado, assinale a alternativa que apresenta, respectivamente, a etapa e as ações a serem adotadas pela Vigilância Epidemiológica em casos como esse.","options":[{"id":"A","text":"Manejo do desastre; decidir sobre as ações de controle de doenças e agravos à saúde.","explanation":""},{"id":"B","text":"Mitigação; monitorar e controlar prioritariamente as doenças transmissíveis.","explanation":""},{"id":"C","text":"Recuperação; intensificar as ações para detecção de doenças-sentinela e de surtos e efetuar a notificação.","explanation":""},{"id":"D","text":"Redução de risco; identificar e mapear a morbimortalidade e apontar as medidas para a redução do risco.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q078","code":"REV-2026.2-Q078","number":78,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q78 · tema a classificar","statement":"Homem de 74 anos, com diagnóstico de transtorno depressivo maior e hipertensão arterial, comparece a uma consulta em Unidade Básica de Saúde referindo episódios de tontura ao se levantar, letargia e confusão mental leve, há 3 semanas. O paciente faz uso de enalapril 10 mg/dia, há 1 ano, e iniciou o uso de paroxetina 40 mg/dia, há 1 mês. O exame físico revela: paciente hidratado, eupneico e orientado; PA 130 x 80 mmHg (sentado) e 115 x 75 mmHg (em pé). Considerando-se esse caso clínico, o exame laboratorial prioritário para a confirmação diagnóstica é a dosagem de","options":[{"id":"A","text":"sódio.","explanation":""},{"id":"B","text":"potássio.","explanation":""},{"id":"C","text":"transaminases.","explanation":""},{"id":"D","text":"creatinina.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q079","code":"REV-2026.2-Q079","number":79,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q79 · tema a classificar","statement":"Homem de 63 anos retorna a determinada Unidade Básica de Saúde com os resultados de exames solicitados para investigação de perda de peso e tosse produtiva, iniciadas há cerca de 6 meses. Nega comorbidades, uso contínuo de medicações ou tratamento para qualquer patologia respiratória prévia. A radiografia de tórax apresenta consolidação em lobo superior direito, sem evidências de cavitação. Teste rápido molecular para tuberculose positivo; resistência à rifampicina não detectada; sorologia para HIV negativa. Após a prescrição do tratamento pertinente, com que frequência esse paciente deve ser monitorado?","options":[{"id":"A","text":"Mensalmente até o término do tratamento.","explanation":""},{"id":"B","text":"Quando houver sintomas respiratórios.","explanation":""},{"id":"C","text":"No início e ao término do tratamento.","explanation":""},{"id":"D","text":"Após 3 e 6 meses do início do tratamento.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q080","code":"REV-2026.2-Q080","number":80,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q80 · tema a classificar","statement":"Determinado médico de uma Unidade Básica de Saúde, durante reunião com equipe interprofissional, discute a ocorrência de cinco casos de hepatite A em crianças de uma ocupação habitacional sem rede de esgoto formal. O Conselho Local de Saúde e a Associação de Moradores relatam insegurança quanto à qualidade da água e dificuldade de adesão às medidas de higiene por falta de insumos. A análise epidemiológica indica que há um grande número de crianças na comunidade que não completaram o esquema vacinal e que a transmissão está ativa no território. Além da vacinação, qual é a próxima ação adequada para essa comunidade?","options":[{"id":"A","text":"Instituir o isolamento das crianças acometidas e de seus familiares.","explanation":""},{"id":"B","text":"Organizar mutirões de limpeza coordenados pela equipe de saúde.","explanation":""},{"id":"C","text":"Acionar a Vigilância Sanitária com vistas à melhoria do tratamento da água.","explanation":""},{"id":"D","text":"Prescrever profilaxia medicamentosa com antivirais para todas as crianças.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q081","code":"REV-2026.2-Q081","number":81,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q81 · tema a classificar","statement":"Homem de 62 anos, diabético, foi submetido a colecistectomia, seguida de colangiopancreatografia retrógrada endoscópica com retirada de cálculo em colédoco, há 3 semanas. Após alta, retorna à emergência hospitalar com queixa de febre, prostração e dor em hipocôndrio direito. Exames revelam: paciente febril; dor à palpação em hipocôndrio direito; hepatimetria de 4 cm do rebordo costal; ausência de dor à descompressão brusca. Os resultados do hemograma são apresentados a seguir. É indicada internação hospitalar, além de antibioticoterapia venosa. Realizada tomografia de abdome, apresentada na seguinte figura. Considerando-se a principal hipótese diagnóstica e a evolução clínica descrita, qual é o manejo para esse paciente?","options":[{"id":"A","text":"Manter tratamento clínico, ampliando o esquema de antibioticoterapia.","explanation":""},{"id":"B","text":"Solicitar sorologia para amebíase e associar antibiótico específico.","explanation":""},{"id":"C","text":"Propor reabordagem cirúrgica e exploração de vias biliares.","explanation":""},{"id":"D","text":"Encaminhar para drenagem percutânea guiada por imagem.","explanation":""}],"correct_option":"D","needs_image":true},{"id":"revalida_2026_2_q082","code":"REV-2026.2-Q082","number":82,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q82 · tema a classificar","statement":"Gestante de 34 anos, na 24ª semana de gestação, é acompanhada em pré-natal de alto risco por história de anemia crônica e cirurgia bariátrica com bypass gástrico em Y de Roux, realizada há 5 anos. Queixa-se de astenia, mas não há sinais de instabilidade hemodinâmica. Está em uso de 200 mg/dia de ferro elementar. Os exames laboratoriais mostram os seguintes resultados. Qual é a conduta terapêutica para essa gestante?","options":[{"id":"A","text":"Manter o ferro elementar e acrescentar ácido fólico.","explanation":""},{"id":"B","text":"Aumentar a dose do ferro elementar e adicionar vitamina B12.","explanation":""},{"id":"C","text":"Prescrever ferro parenteral.","explanation":""},{"id":"D","text":"Transfundir concentrado de hemácias.","explanation":""}],"correct_option":"C","needs_image":true},{"id":"revalida_2026_2_q083","code":"REV-2026.2-Q083","number":83,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q83 · tema a classificar","statement":"Mulher de 48 anos procurou uma Unidade Básica de Saúde (UBS) devido a dor crônica generalizada persistente. Relata que, em consulta com outro médico, recebeu o diagnóstico de fibromialgia e que, desde então, tem feito diversos tratamentos, mas sem resultados. Diante disso, a paciente solicita a prescrição de Cannabis medicinal. Qual é o papel do médico da UBS em relação ao uso da Cannabis medicinal nesse caso?","options":[{"id":"A","text":"Prescrevê-la, visto que ela consta na relação nacional de medicamentos excepcionais do SUS.","explanation":""},{"id":"B","text":"Solicitar autorização do Conselho Regional de Medicina para sua prescrição no SUS.","explanation":""},{"id":"C","text":"Informar que faltam evidências que sustentem seu uso e sua prescrição no SUS.","explanation":""},{"id":"D","text":"Comunicar que seu uso e sua prescrição no SUS devem ocorrer mediante autorização judicial.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q084","code":"REV-2026.2-Q084","number":84,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q84 · tema a classificar","statement":"Adolescente de 16 anos, assintomática, procura atendimento em uma Unidade de Saúde da Família, sozinha. Em consulta, informa que iniciou atividade sexual consentida com um colega da escola, de mesma idade, razão pela qual pede ao médico que coloque nela um implante contraceptivo de longa duração. Refere que seus pais têm ciência do namoro, mas não sabem que ela iniciou sua vida sexual. Qual é a conduta adequada do médico nesse caso?","options":[{"id":"A","text":"Encaminhar a paciente para o serviço ginecológico.","explanation":""},{"id":"B","text":"Acionar o Conselho Tutelar da Criança e do Adolescente.","explanation":""},{"id":"C","text":"Comunicar aos pais da paciente o desejo de anticoncepção.","explanation":""},{"id":"D","text":"Atender ao pedido feito pela paciente quanto à anticoncepção.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q085","code":"REV-2026.2-Q085","number":85,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q85 · tema a classificar","statement":"Homem de 44 anos, com histórico de esquizofrenia, conhecido da equipe de uma Unidade Básica de Saúde, foi encontrado por uma agente comunitária de saúde em situação de rua e estava sem uso de medicamentos há vários meses. Tem histórico de múltiplas internações psiquiátricas e de má adesão aos tratamentos no Centro de Atenção Psicossocial. Após o acolhimento, quais ações são indicadas para esse caso?","options":[{"id":"A","text":"Administrar antipsicótico de longa duração e encaminhar à assistência social.","explanation":""},{"id":"B","text":"Iniciar processo de curatela e recomendar a internação compulsória.","explanation":""},{"id":"C","text":"Acionar a rede de atenção psicossocial e articular o cuidado intersetorial.","explanation":""},{"id":"D","text":"Resgatar vínculo familiar e promover institucionalização.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q086","code":"REV-2026.2-Q086","number":86,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q86 · tema a classificar","statement":"Homem de 42 anos está sob investigação em Unidade Básica de Saúde, devido a aumento progressivo do volume abdominal e astenia. O paciente é natural e residente de uma cidade no interior da Bahia, nunca tendo viajado para fora do seu estado. Nega etilismo. O exame físico revela ascite moderada e circulação colateral na parede abdominal. A ultrassonografia mostra: fígado de dimensões preservadas, bordas rombas e sem nodulações; presença de fibrose periportal; esplenomegalia e aumento do calibre da veia porta e líquido ascítico na cavidade peritoneal. A endoscopia digestiva alta indica varizes esofágicas. Qual o exame indicado para confirmação da principal hipótese diagnóstica?","options":[{"id":"A","text":"Doppler de sistema portal.","explanation":""},{"id":"B","text":"Paracentese diagnóstica.","explanation":""},{"id":"C","text":"Sorologia de hepatites virais.","explanation":""},{"id":"D","text":"Exame parasitológico.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q087","code":"REV-2026.2-Q087","number":87,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q87 · tema a classificar","statement":"Adolescente de 15 anos, acompanhada pelos pais, é atendida em Unidade Básica de Saúde. A mãe relata que a paciente passa quase todo o tempo no quarto e não conversa com os familiares, preferindo usar o celular. Durante exame físico, a sós com a médica, a paciente refere estar apaixonada por uma colega de classe e afirma que tem medo de que os pais descubram. Reforça que “gosta de garotas” e se reconhece como mulher. Refere, ainda, que, devido à angústia relacionada ao preconceito da família, vem fazendo cortes em face interna de coxas, para “diminuir o sofrimento”. Ao final, pede à médica que não conte nada disso aos pais. Considerando-se o caso descrito, qual é a conduta adequada a ser adotada pela médica?","options":[{"id":"A","text":"Preservar sigilo sobre a orientação sexual e revelar aos pais os comportamentos autolesivos.","explanation":""},{"id":"B","text":"Guardar sigilo tanto sobre a orientação sexual quanto sobre os comportamentos autolesivos.","explanation":""},{"id":"C","text":"Revelar aos pais as informações referentes à orientação sexual e aos comportamentos autolesivos.","explanation":""},{"id":"D","text":"Manter sigilo sobre os comportamentos autolesivos e revelar aos pais a orientação sexual.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q088","code":"REV-2026.2-Q088","number":88,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q88 · tema a classificar","statement":"Homem de 32 anos estava internado para tratamento de criptococose encefálica. Durante a internação, relatou ao seu médico ser pessoa vivendo com HIV (PVHIV) e portador de tuberculose, sem tratamentos, e entregou-lhe documento em que solicitava que sua condição de saúde não fosse revelada a nenhum familiar, inclusive para sua mãe e seu companheiro. Ainda durante a internação, devido a derrame pleural tuberculoso volumoso, necessitou ser submetido à drenagem pleural. No sétimo dia após o procedimento, apresentou sangramento intenso pelo dreno de tórax, sendo submetido à toracotomia de urgência. Foi identificada lesão aórtica com sangramento ativo e impossível de ser contido. Apesar de todos os esforços da equipe médica, o paciente evoluiu a óbito intraoperatório. Assinale a alternativa que apresenta o correto preenchimento da declaração de óbito nessa situação, na ordem da causa terminal para a básica.","options":[{"id":"A","text":"Hemorragia torácica, choque hipovolêmico, rotura aórtica, tuberculose.","explanation":""},{"id":"B","text":"Choque hipovolêmico, rotura aórtica, tuberculose, PVHIV.","explanation":""},{"id":"C","text":"Tuberculose, PVHIV, criptococose encefálica, choque hipovolêmico.","explanation":""},{"id":"D","text":"Rotura aórtica, choque hipovolêmico, PVHIV, criptococose encefálica.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q089","code":"REV-2026.2-Q089","number":89,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q89 · tema a classificar","statement":"Mulher de 72 anos, diabética, procura atendimento devido a uma lesão pruriginosa em vulva, há 8 meses. Fez uso de corticosteroides tópicos e aciclovir por 6 semanas, sem melhora dos sintomas ou redução da lesão. O exame físico revela: lesão no lábio externo, arredondada, circunscrita, ulcerada, com 3 cm de diâmetro, bordas discretamente elevadas e pouco definidas, fundo hiperemiado e granulado, com depósitos esbranquiçados na região central. Considerando-se o caso clínico, qual é o exame indicado para confirmar a hipótese diagnóstica?","options":[{"id":"A","text":"Esfregaço da lesão para coloração de Gram.","explanation":""},{"id":"B","text":"Genotipagem de HPV.","explanation":""},{"id":"C","text":"Biópsia da lesão.","explanation":""},{"id":"D","text":"Vulvoscopia com ácido acético.","explanation":""}],"correct_option":"C","needs_image":true},{"id":"revalida_2026_2_q090","code":"REV-2026.2-Q090","number":90,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q90 · tema a classificar","statement":"Agricultor de 65 anos chega a uma Unidade Básica de Saúde com história de febre não aferida há 5 dias, tosse com expectoração purulenta, fraqueza e cansaço aos esforços. É tabagista e etilista. O exame físico mostra: paciente consciente e colaborativo; PA 100 x 70 mmHG; FC 84 bpm; FR 16 irpm; SpO₂ 96% em ar ambiente; sem esforço respiratório; ausculta pulmonar com estertores em base direita e sem outras alterações. Qual é o manejo adequado para esse paciente?","options":[{"id":"A","text":"Indicar internação para antibioticoterapia parenteral.","explanation":""},{"id":"B","text":"Encaminhar ao pronto atendimento para radiografia de tórax prévia.","explanation":""},{"id":"C","text":"Prescrever antibioticoterapia oral com reavaliação em 48 horas.","explanation":""},{"id":"D","text":"Solicitar exames laboratoriais para diagnóstico etiológico.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q091","code":"REV-2026.2-Q091","number":91,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q91 · tema a classificar","statement":"Adolescente de 15 anos, com quadro de transtorno do espectro autista, é levado pela mãe a uma Unidade de Pronto Atendimento após ter apresentado, na escola, episódio de agitação progressiva, vocalizações intensas e repetitivas, movimentos amplos dos membros superiores, chegando a cair ao chão. Durante todo o episódio, manteve os olhos abertos e reagia aos estímulos do ambiente. Não houve liberação esfincteriana, confusão mental ou sonolência após o episódio. O quadro em questão é compatível com o diagnóstico de crise","options":[{"id":"A","text":"epiléptica.","explanation":""},{"id":"B","text":"de ansiedade aguda.","explanation":""},{"id":"C","text":"conversiva.","explanation":""},{"id":"D","text":"de desregulação comportamental.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q092","code":"REV-2026.2-Q092","number":92,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q92 · tema a classificar","statement":"Lactente de 3 meses é levado a uma Unidade Básica de Saúde por apresentar crises de tosse intensa há 15 dias, acentuando-se há 10 dias em crises sucessivas, com associação de vômitos. Durante as crises, apresenta cianose, hemorragia conjuntival, petéquias e rubor facial. Foi realizada imunização somente ao nascimento. Qual exame deve ser realizado para confirmação da hipótese diagnóstica nesse caso?","options":[{"id":"A","text":"Bacterioscopia pelo Gram em amostra de swab de nasofaringe.","explanation":""},{"id":"B","text":"Hemograma com contagem de plaquetas.","explanation":""},{"id":"C","text":"Reação em cadeia da polimerase em amostra de swab de nasofaringe.","explanation":""},{"id":"D","text":"Sorologia para toxina em amostra de sangue.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q093","code":"REV-2026.2-Q093","number":93,"area":"CIRURGIA_GERAL","topic":"Revalida 2026/2 · Q93 · tema a classificar","statement":"Homem de 45 anos foi submetido a colecistectomia laparoscópica eletiva, devido a litíase não complicada. No dia seguinte à cirurgia, apresentou temperatura axilar de 37,5 °C, dor abdominal difusa e FC 110 bpm. O médico assistente deu alta ao paciente, atribuindo as queixas ao processo normal de recuperação. O paciente retornou para reavaliação no 4º dia de pós-operatório, com piora do quadro clínico. A ultrassonografia abdominal identificou grande quantidade de líquido livre abdominal, e a reabordagem cirúrgica mostrou fístula biliar. Após a recuperação, a família do paciente decidiu buscar orientação jurídica. A situação descrita configura","options":[{"id":"A","text":"negligência.","explanation":""},{"id":"B","text":"imprudência.","explanation":""},{"id":"C","text":"diligência.","explanation":""},{"id":"D","text":"omissão de socorro.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q094","code":"REV-2026.2-Q094","number":94,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q94 · tema a classificar","statement":"Adolescente de 16 anos comparece à consulta em ambulatório de ginecologia referindo ainda não ter menstruado, a despeito de ter apresentado telarca aos 10 anos e pubarca logo em seguida. Ela não tem outras queixas. Tem 1,68 m de estatura e pesa 65 kg. A paciente tem pilificação axilar habitual, acne grau II em face, tórax e região dorsal. O exame ginecológico mostra: mamas com configuração normal; distribuição de pelos pubianos adequada para o sexo feminino; órgãos genitais externos sem alterações evidentes; hímen íntegro, com orifício orbicular permeável. No exame, não se procedeu ao toque vaginal. Considerando-se o caso descrito, qual é a hipótese diagnóstica a ser investigada?","options":[{"id":"A","text":"Síndrome de Turner.","explanation":""},{"id":"B","text":"Insensibilidade androgênica.","explanation":""},{"id":"C","text":"Amenorreia hipotalâmica primária.","explanation":""},{"id":"D","text":"Anomalia Mülleriana.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q095","code":"REV-2026.2-Q095","number":95,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q95 · tema a classificar","statement":"Homem de 53 anos, em consulta a uma Unidade Básica de Saúde (UBS), vigilante, viúvo, relata que perdeu a esposa e um filho de 17 anos em uma tentativa de assalto, há 2 anos. Refere aumento progressivo do consumo de álcool e isolamento social desde o ocorrido. Informa que, durante a semana, ingere cerca de 2 latas de cerveja após o trabalho e, aos finais de semana, consome uma caixa de cerveja ao dia. Afirma também que, ultimamente, tem recebido reclamações do chefe, pois tem chegado atrasado ao trabalho. Nega episódios de “apagões”, agressões ou acidentes. Ao exame psíquico, apresenta humor deprimido e sono fragmentado. Nega plano suicida no momento. Não há sinais de abstinência aguda nem alterações ao exame físico. Qual deve ser a abordagem inicial nesse caso?","options":[{"id":"A","text":"Diagnosticar o abuso de álcool utilizando o questionário CAGE e prescrever antidepressivo tricíclico.","explanation":""},{"id":"B","text":"Utilizar a abordagem de redução de danos no manejo do consumo de álcool e prescrever dissulfiran.","explanation":""},{"id":"C","text":"Realizar intervenção breve e terapia multiprofissional na UBS para abordagem do consumo de álcool.","explanation":""},{"id":"D","text":"Encaminhar paciente para internação hospitalar de curta duração e envolver os familiares no plano de cuidado.","explanation":""}],"correct_option":"C","needs_image":false},{"id":"revalida_2026_2_q096","code":"REV-2026.2-Q096","number":96,"area":"CLINICA_MEDICA","topic":"Revalida 2026/2 · Q96 · tema a classificar","statement":"Mulher de 38 anos é atendida em Unidade Básica de Saúde para investigação de quadro de emagrecimento e palpitações. Relata que o emagrecimento não é intencional e que seu apetite está preservado. Além disso, refere incomodar-se muito com a sensação de palpitações esporádicas, sentidas geralmente durante o esforço, mas também, por vezes, mesmo em repouso. O exame físico revela: PA 160 x 80 mmHg; FC 132 bpm em repouso; exoftalmia; pele quente e úmida e alopecia generalizada. Exames laboratoriais mostram os seguintes resultados: Qual esquema terapêutico deve ser instituído nesse caso?","options":[{"id":"A","text":"Metimazol e propranolol.","explanation":""},{"id":"B","text":"Propiltiouracil e amiodarona.","explanation":""},{"id":"C","text":"Carbonato de lítio e propafenona.","explanation":""},{"id":"D","text":"Iodo radioativo e procainamida.","explanation":""}],"correct_option":"A","needs_image":true},{"id":"revalida_2026_2_q097","code":"REV-2026.2-Q097","number":97,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q97 · tema a classificar","statement":"Criança de 3 anos é levada para consulta de rotina. Apresenta-se irritada, com relato materno de febre intermitente e perda ponderal de 2 kg nos últimos 2 meses. O exame físico mostra que a PA está no percentil 95 para a idade e altura. Nota-se presença de equimoses periorbitárias bilaterais e de massa firme em flanco direito que ultrapassa a linha média abdominal. Qual é o diagnóstico mais provável nessa situação?","options":[{"id":"A","text":"Tumor de Wilms.","explanation":""},{"id":"B","text":"Neuroblastoma.","explanation":""},{"id":"C","text":"Rabdomiossarcoma.","explanation":""},{"id":"D","text":"Linfoma de Burkitt.","explanation":""}],"correct_option":"B","needs_image":false},{"id":"revalida_2026_2_q098","code":"REV-2026.2-Q098","number":98,"area":"PEDIATRIA","topic":"Revalida 2026/2 · Q98 · tema a classificar","statement":"Menina de 1 ano é levada a uma Unidade de Pronto Atendimento com história de abaulamento em região inguinal até o lábio maior esquerdo, há cerca de 6 meses. O exame físico revela abaulamento inguinal esquerdo, com conteúdo fibroelástico, pequeno e redutível. Qual é a conduta adequada nesse caso?","options":[{"id":"A","text":"Indicar cirurgia eletiva.","explanation":""},{"id":"B","text":"Encaminhar para cirurgia de urgência.","explanation":""},{"id":"C","text":"Manter conduta expectante.","explanation":""},{"id":"D","text":"Prescrever gonadotrofina coriônica.","explanation":""}],"correct_option":"A","needs_image":false},{"id":"revalida_2026_2_q099","code":"REV-2026.2-Q099","number":99,"area":"GINECOLOGIA_OBSTETRICIA","topic":"Revalida 2026/2 · Q99 · tema a classificar","statement":"Paciente, G3P1A1, com gestação de 13 semanas, datada pela ecografia de 8 semanas, procura pronto atendimento devido à queixa de sangramento vaginal iniciado há 3 dias, em pequena quantidade. A tipagem sanguínea anotada no cartão de pré-natal é A negativo. Ela desconhece a tipagem sanguínea de seu parceiro. O exame ginecológico mostra sangue escurecido em moderada quantidade na vagina e colo uterino fechado. É solicitado teste de coombs indireto, cujo resultado é positivo. Qual a conduta nesse momento?","options":[{"id":"A","text":"Alertar paciente sobre a inviabilidade da gestação.","explanation":""},{"id":"B","text":"Realizar imunoglobulina anti-RH.","explanation":""},{"id":"C","text":"Solicitar tipagem sanguínea do parceiro.","explanation":""},{"id":"D","text":"Encaminhar paciente ao pré-natal de alto risco.","explanation":""}],"correct_option":"D","needs_image":false},{"id":"revalida_2026_2_q100","code":"REV-2026.2-Q100","number":100,"area":"MEDICINA_FAMILIA_COMUNIDADE","topic":"Revalida 2026/2 · Q100 · tema a classificar","statement":"Após a ocorrência de grandes ondas de calor em determinada região, idosa de 72 anos procura atendimento em Unidade Básica de Saúde por apresentar tontura, fraqueza, cefaleia pulsátil e redução do volume urinário. Ela refere ser hipertensa e morar em uma casa pequena com pouca ventilação. Nega outras comorbidades ou sintomas adicionais. O exame físico mostra PA 100 x 60 mmHg, FC 110 bpm, mucosas secas e temperatura axilar de 38 °C. A equipe de saúde observa que outros moradores da área estão nas mesmas condições dessa paciente. Nessa situação, quais são as estratégias adequadas a serem adotadas, nas abordagens individual e coletiva, respectivamente?","options":[{"id":"A","text":"Prescrever antitérmicos, antieméticos e resfriamento corporal; mobilizar os agentes comunitários na orientação das famílias quanto às medidas para amenizar os efeitos do calor.","explanation":""},{"id":"B","text":"Iniciar reposição hidroeletrolítica e encaminhar paciente ao pronto-socorro; notificar caso à Secretaria de Saúde para intervenções nesse território.","explanation":""},{"id":"C","text":"Orientar o aumento da ingestão hídrica em domicílio; realizar reunião de equipe para organizar o fluxo assistencial desses atendimentos.","explanation":""},{"id":"D","text":"Indicar reposição hídrica, resfriamento corporal e monitorização; realizar a vigilância ativa de idosos vulneráveis com ações intersetoriais.","explanation":""}],"correct_option":"D","needs_image":false}]$carga_dados$::jsonb;
  v_fontes constant jsonb := $carga_fontes$[{"year":2026,"title":"Gabarito oficial do Inep — Revalida INEP 2026/2 — 2ª Edição Semestral","reliability":"OFICIAL_INEP","organization":"INEP / MEC"}]$carga_fontes$::jsonb;
  r jsonb;
  v_id text;
  v_novas integer := 0;
begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'exams' and column_name = 'final_answer_expected_on') then
    raise exception 'Cole antes a parte 1 (1-aviso-gabarito-preliminar.sql). Nada foi mudado.';
  end if;
  insert into public.exams (id, kind, year, semester, title)
  values ('revalida-2026-2', 'REVALIDA', 2026, 2, 'Revalida INEP 2026/2 — 2ª Edição Semestral')
  on conflict (id) do nothing;
  -- a data do definitivo: só grava se ainda está vazia (quem trocou depois não é desfeito por uma nova colagem)
  update public.exams set final_answer_expected_on = '2026-12-04'::date where id = 'revalida-2026-2' and final_answer_expected_on is null;
  for r in select value from jsonb_array_elements(v_dados) loop
    v_id := null;
    insert into public.questions (id, code, exam_id, number, area, topic, statement, options, correct_option, status, needs_image, images, sources)
    values (r ->> 'id', r ->> 'code', 'revalida-2026-2', (r ->> 'number')::int, (r ->> 'area')::public.med_area, r ->> 'topic', r ->> 'statement',
            r -> 'options', r ->> 'correct_option', 'valid', (r ->> 'needs_image')::boolean, '[]'::jsonb, v_fontes)
    on conflict do nothing
    returning id into v_id;
    if v_id is not null then
      v_novas := v_novas + 1;
      insert into public.question_change_log (question_id, changed_by, reason, changes)
      values (v_id, null, 'Prova nova: Revalida 2026/2 (texto do caderno 1 do Inep). Gabarito preliminar: questão do Revalida 2026/2, ainda sem gabarito definitivo do Inep.', jsonb_build_object('criacao', jsonb_build_object('de', null, 'para', 'revalida-2026-2#' || (r ->> 'number'))));
      insert into _carga_2026_2_resultado values (r ->> 'code', 'criada agora');
    else
      insert into _carga_2026_2_resultado values (r ->> 'code', 'já existia (não mexi)');
    end if;
    -- gabarito oficial: só quando a questão ainda não tem nenhum registrado
    if exists (select 1 from public.questions q where q.id = r ->> 'id' and q.exam_id = 'revalida-2026-2')
       and not exists (select 1 from public.question_official_answers o where o.question_id = r ->> 'id') then
      insert into public.question_official_answers (question_id, answer, answer_status, published_at, source, source_url)
      values (r ->> 'id', r ->> 'correct_option', 'PRELIMINARY', null, 'Gabarito preliminar do Inep — Revalida 2026/2, caderno 1 (2026_2_gabarito_preliminar_caderno1.pdf). Gabarito preliminar: questão do Revalida 2026/2, ainda sem gabarito definitivo do Inep.', null);
      insert into _carga_2026_2_resultado values (r ->> 'code', 'gabarito preliminar registrado');
    end if;
  end loop;
  perform public.admin_refresh_exam_counts();
  if v_novas > 0 then
    perform public.admin_log('questions.import', null, jsonb_build_object('inserted', v_novas, 'updated', 0, 'skipped', jsonb_array_length(v_dados) - v_novas,
      'prova', 'revalida-2026-2', 'reason', 'Gabarito preliminar: questão do Revalida 2026/2, ainda sem gabarito definitivo do Inep'));
  end if;
end
$carga_2026_2$;

select resultado, detalhe from (
  select 0 as ordem,
         case when (select count(*) from public.questions where exam_id = 'revalida-2026-2') >= 100
                   and (select count(*) from public.question_official_answers o join public.questions q on q.id = o.question_id
                        where q.exam_id = 'revalida-2026-2' and o.is_current) >= 100
              then 'OK: ' else 'ATENÇÃO: ' end
         || 'Revalida 2026/2: ' || (select count(*) from public.questions where exam_id = 'revalida-2026-2') || ' questões no banco ('
         || (select count(*) from _carga_2026_2_resultado where situacao = 'criada agora') || ' criadas agora); gabarito atual: '
         || coalesce((select string_agg(s || ' ' || n, ', ') from (select o.answer_status s, count(*) n from public.question_official_answers o
                      join public.questions q on q.id = o.question_id where q.exam_id = 'revalida-2026-2' and o.is_current group by 1) z), 'nenhum') as resultado,
         'gabarito definitivo previsto (selo do aluno): ' || coalesce(to_char((select final_answer_expected_on from public.exams where id = 'revalida-2026-2'), 'DD/MM/YYYY'), 'sem data')
          as detalhe
) x order by ordem;
